import { useState } from "react";
import AdminDashboard from "./components/AdminDashboard.jsx";
import ReportFeed from "./components/ReportFeed.jsx";
import ReportForm from "./components/ReportForm.jsx";

const tabs = [
  { id: "form", label: "Report an Issue" },
  { id: "feed", label: "Live Feed" },
  { id: "admin", label: "Admin Dashboard" },
];

export default function App() {
  const [activeTab, setActiveTab] = useState("form");

  return (
    <main className="min-h-screen bg-slate-50">
      <header className="border-b border-slate-200 bg-white">
        <div className="mx-auto flex max-w-7xl flex-col gap-4 px-4 py-5 sm:px-6 lg:flex-row lg:items-center lg:justify-between lg:px-8">
          <a
            className="text-2xl font-bold tracking-tight text-emerald-800"
            href="/"
            onClick={(event) => {
              event.preventDefault();
              setActiveTab("form");
            }}
          >
            CivicGuard
          </a>

          <nav aria-label="Main navigation" className="flex flex-wrap gap-2" role="tablist">
            {tabs.map((tab) => {
              const isActive = activeTab === tab.id;

              return (
                <button
                  aria-selected={isActive}
                  className={`rounded-lg px-4 py-2 text-sm font-medium transition focus:outline-none focus:ring-4 focus:ring-emerald-600/20 ${
                    isActive
                      ? "bg-emerald-700 text-white shadow-sm"
                      : "text-slate-600 hover:bg-slate-100 hover:text-slate-900"
                  }`}
                  key={tab.id}
                  onClick={() => setActiveTab(tab.id)}
                  role="tab"
                  type="button"
                >
                  {tab.label}
                </button>
              );
            })}
          </nav>
        </div>
      </header>

      <div className="mx-auto max-w-7xl px-4 py-8 sm:px-6 sm:py-10 lg:px-8">
        {activeTab === "form" ? (
          <ReportForm />
        ) : activeTab === "feed" ? (
          <ReportFeed />
        ) : (
          <AdminDashboard />
        )}
      </div>
    </main>
  );
}

