import { useEffect, useMemo, useState } from "react";

const API_URL = "http://localhost:5000/api/reports";

const urgencyStyles = {
  low: "bg-emerald-100 text-emerald-800 ring-emerald-600/20",
  medium: "bg-amber-100 text-amber-800 ring-amber-600/20",
  high: "bg-orange-100 text-orange-800 ring-orange-600/20",
  critical: "bg-rose-100 text-rose-800 ring-rose-600/20",
};

const categoryStyles = {
  pothole: "bg-orange-50 text-orange-700",
  streetlight: "bg-yellow-50 text-yellow-800",
  accessibility: "bg-blue-50 text-blue-700",
  garbage: "bg-lime-50 text-lime-800",
};

function getSeverity(value) {
  if (typeof value === "string") {
    const normalized = value.trim().toLowerCase();
    const severityByLabel = {
      low: 1,
      minor: 1,
      medium: 3,
      moderate: 3,
      high: 4,
      severe: 4,
      critical: 5,
    };

    if (normalized in severityByLabel) return severityByLabel[normalized];
  }

  const score = Number(value);
  return Number.isFinite(score) && score >= 1 && score <= 5
    ? Math.round(score)
    : null;
}

function getUrgency(value, severity) {
  const normalized = typeof value === "string" ? value.trim().toLowerCase() : "";
  if (["low", "medium", "high", "critical"].includes(normalized)) {
    return normalized;
  }

  if (severity === null) return "medium";
  if (severity >= 5) return "critical";
  if (severity >= 4) return "high";
  if (severity >= 3) return "medium";
  return "low";
}

function getReportDetails(report) {
  const analysis =
    report.analysis && typeof report.analysis === "object" ? report.analysis : {};
  const category = String(report.category ?? analysis.category ?? "Uncategorized");
  const description = String(
    report.description ?? analysis.summary ?? analysis.description ?? "No description provided.",
  );
  const severity = getSeverity(
    analysis.severityScore ??
      analysis.severity_score ??
      analysis.severity ??
      report.severityScore ??
      report.severity,
  );
  const urgency = getUrgency(
    analysis.urgencyLevel ?? analysis.urgency ?? report.urgency,
    severity,
  );
  const timestamp = report.timestamp ?? report.createdAt ?? report.created_at;
  const date = timestamp ? new Date(timestamp) : null;

  return {
    id: report.id,
    title: String(
      report.title ?? analysis.title ?? analysis.issueTitle ?? `${category} report`,
    ),
    category,
    description,
    severity,
    urgency,
    timestamp:
      date && !Number.isNaN(date.getTime())
        ? new Intl.DateTimeFormat(undefined, {
            dateStyle: "medium",
            timeStyle: "short",
          }).format(date)
        : "Time unavailable",
  };
}

function SeverityIndicator({ score }) {
  return (
    <div aria-label={score ? `Severity ${score} out of 5` : "Severity not rated"}>
      <div aria-hidden="true" className="mt-2 flex items-center gap-1.5">
        {[1, 2, 3, 4, 5].map((level) => (
          <span
            className={`h-2 flex-1 rounded-full ${
              score !== null && level <= score ? "bg-rose-500" : "bg-slate-200"
            }`}
            key={level}
          />
        ))}
      </div>
      <p className="mt-1.5 text-xs font-medium text-slate-600">
        {score === null ? "Not rated" : `${score} / 5`}
      </p>
    </div>
  );
}

export default function ReportFeed() {
  const [reports, setReports] = useState([]);
  const [search, setSearch] = useState("");
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");

  useEffect(() => {
    const controller = new AbortController();

    async function loadReports() {
      try {
        const response = await fetch(API_URL, { signal: controller.signal });
        if (!response.ok) {
          throw new Error(`Could not load reports (${response.status}).`);
        }

        const data = await response.json();
        if (!Array.isArray(data)) {
          throw new Error("The reports response was not a list.");
        }

        setReports(data);
      } catch (fetchError) {
        if (fetchError.name !== "AbortError") {
          setError(fetchError.message || "Could not load reports.");
        }
      } finally {
        if (!controller.signal.aborted) setLoading(false);
      }
    }

    loadReports();
    return () => controller.abort();
  }, []);

  const reportDetails = useMemo(
    () => reports.map(getReportDetails),
    [reports],
  );
  const filteredReports = useMemo(() => {
    const query = search.trim().toLowerCase();
    if (!query) return reportDetails;

    return reportDetails.filter((report) =>
      [report.category, report.title, report.description, report.urgency]
        .join(" ")
        .toLowerCase()
        .includes(query),
    );
  }, [reportDetails, search]);

  return (
    <section className="mx-auto w-full max-w-7xl">
      <div className="mb-7 flex flex-col gap-4 sm:flex-row sm:items-end sm:justify-between">
        <div>
          <p className="text-sm font-semibold uppercase tracking-wide text-emerald-700">
            CivicGuard community
          </p>
          <h1 className="mt-1 text-2xl font-bold tracking-tight text-slate-900 sm:text-3xl">
            Live Feed
          </h1>
          <p className="mt-2 text-sm leading-6 text-slate-600">
            Browse reported issues and see what needs attention in your area.
          </p>
        </div>

        <label className="block w-full sm:max-w-sm">
          <span className="sr-only">Search reports by category or keyword</span>
          <input
            className="block w-full rounded-lg border border-slate-300 bg-white px-4 py-2.5 text-sm text-slate-900 shadow-sm outline-none transition placeholder:text-slate-400 focus:border-emerald-600 focus:ring-4 focus:ring-emerald-600/15"
            onChange={(event) => setSearch(event.target.value)}
            placeholder="Search reports..."
            type="search"
            value={search}
          />
        </label>
      </div>

      {loading ? (
        <p aria-live="polite" className="rounded-xl bg-white p-6 text-slate-600 shadow-sm">
          Loading reports…
        </p>
      ) : error ? (
        <p
          aria-live="polite"
          className="rounded-xl border border-rose-200 bg-rose-50 p-6 text-sm text-rose-800"
          role="alert"
        >
          {error} Make sure the CivicGuard API is running and try again.
        </p>
      ) : filteredReports.length === 0 ? (
        <div className="rounded-xl border border-dashed border-slate-300 bg-white px-5 py-12 text-center">
          <p className="font-medium text-slate-800">
            {search ? "No matching reports" : "No reports yet"}
          </p>
          <p className="mt-1 text-sm text-slate-500">
            {search
              ? "Try a different category or keyword."
              : "New community reports will appear here."}
          </p>
        </div>
      ) : (
        <div className="grid grid-cols-1 gap-6 md:grid-cols-2 lg:grid-cols-3">
          {filteredReports.map((report, index) => {
            const categoryStyle =
              categoryStyles[report.category.toLowerCase()] ??
              "bg-slate-100 text-slate-700";

            return (
              <article
                className="flex h-full flex-col rounded-2xl border border-slate-200 bg-white p-5 shadow-sm transition hover:-translate-y-0.5 hover:shadow-md"
                key={report.id ?? `${report.title}-${report.timestamp}-${index}`}
              >
                <div className="flex items-start justify-between gap-3">
                  <span
                    className={`inline-flex rounded-full px-2.5 py-1 text-xs font-semibold ${categoryStyle}`}
                  >
                    {report.category}
                  </span>
                  <span
                    className={`shrink-0 rounded-full px-2.5 py-1 text-xs font-semibold capitalize ring-1 ring-inset ${urgencyStyles[report.urgency]}`}
                  >
                    {report.urgency} urgency
                  </span>
                </div>

                <h2 className="mt-4 text-lg font-semibold leading-6 text-slate-900">
                  {report.title}
                </h2>
                <p className="mt-2 flex-1 whitespace-pre-line text-sm leading-6 text-slate-600">
                  {report.description}
                </p>

                <div className="mt-5 border-t border-slate-100 pt-4">
                  <div className="flex items-center justify-between gap-4">
                    <p className="text-sm font-medium text-slate-700">Severity</p>
                    <time className="text-right text-xs text-slate-500">
                      {report.timestamp}
                    </time>
                  </div>
                  <SeverityIndicator score={report.severity} />
                </div>
              </article>
            );
          })}
        </div>
      )}
    </section>
  );
}

