import { useEffect, useMemo, useState } from "react";

const API_URL = "http://localhost:5000/api/reports";
const statuses = ["Pending", "In Progress", "Resolved"];
const urgencyOrder = { critical: 4, high: 3, medium: 2, low: 1 };

const urgencyStyles = {
  critical: "bg-red-100 text-red-800 ring-red-600/20",
  high: "bg-orange-100 text-orange-800 ring-orange-600/20",
  medium: "bg-yellow-100 text-yellow-800 ring-yellow-600/20",
  low: "bg-slate-100 text-slate-700 ring-slate-600/20",
};

const statusStyles = {
  Pending: "bg-yellow-100 text-yellow-800",
  "In Progress": "bg-blue-100 text-blue-800",
  Resolved: "bg-green-100 text-green-800",
};

function normalizeReport(report, index) {
  const analysis =
    report.analysis && typeof report.analysis === "object" ? report.analysis : {};
  const severityValue =
    report.severityScore ??
    report.severity_score ??
    analysis.severityScore ??
    analysis.severity_score ??
    analysis.severity;
  const severityNumber = Number(severityValue);
  const severityScore =
    Number.isFinite(severityNumber) && severityNumber >= 1 && severityNumber <= 5
      ? Math.round(severityNumber)
      : null;
  const urgencyLevel = String(
    report.urgencyLevel ??
      report.urgency ??
      analysis.urgencyLevel ??
      analysis.urgency ??
      "Low",
  );
  const category = String(report.category ?? analysis.category ?? "Uncategorized");

  return {
    id: String(report.id ?? `report-${index}`),
    title: String(
      report.title ?? analysis.title ?? analysis.issueTitle ?? `${category} report`,
    ),
    category,
    description: String(
      report.description ??
        analysis.summary ??
        analysis.description ??
        "No description provided.",
    ),
    urgencyLevel,
    severityScore,
    timestamp: report.timestamp ?? report.createdAt ?? report.created_at,
    status: statuses.includes(report.status) ? report.status : "Pending",
  };
}

function formatTimestamp(timestamp) {
  if (!timestamp) return "—";
  const date = new Date(timestamp);
  if (Number.isNaN(date.getTime())) return "—";

  return new Intl.DateTimeFormat(undefined, {
    dateStyle: "medium",
    timeStyle: "short",
  }).format(date);
}

function SummaryCard({ label, value, detail, accent }) {
  return (
    <article className="rounded-xl border border-slate-200 bg-white p-5 shadow-sm">
      <p className="text-sm font-medium text-slate-600">{label}</p>
      <p className={`mt-2 text-3xl font-bold tracking-tight ${accent}`}>{value}</p>
      <p className="mt-1 text-xs text-slate-500">{detail}</p>
    </article>
  );
}

export default function AdminDashboard() {
  const [reports, setReports] = useState([]);
  const [statusById, setStatusById] = useState({});
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");

  useEffect(() => {
    const controller = new AbortController();

    async function loadReports() {
      try {
        const response = await fetch(API_URL, { signal: controller.signal });
        if (!response.ok) {
          throw new Error(`Could not load reports (${response.status}).`);
        }

        const data = await response.json();
        if (!Array.isArray(data)) {
          throw new Error("The reports response was not a list.");
        }

        const normalizedReports = data.map(normalizeReport);
        setReports(normalizedReports);
        setStatusById(
          Object.fromEntries(
            normalizedReports.map((report) => [report.id, report.status]),
          ),
        );
      } catch (loadError) {
        if (loadError.name !== "AbortError") {
          setError(loadError.message || "Could not load reports.");
        }
      } finally {
        if (!controller.signal.aborted) setLoading(false);
      }
    }

    loadReports();
    return () => controller.abort();
  }, []);

  const sortedReports = useMemo(
    () =>
      [...reports].sort((first, second) => {
        const firstUrgency =
          urgencyOrder[first.urgencyLevel.toLowerCase()] ?? 0;
        const secondUrgency =
          urgencyOrder[second.urgencyLevel.toLowerCase()] ?? 0;

        return (
          secondUrgency - firstUrgency ||
          (second.severityScore ?? 0) - (first.severityScore ?? 0)
        );
      }),
    [reports],
  );

  const criticalCount = reports.filter(
    (report) => report.urgencyLevel.toLowerCase() === "critical",
  ).length;
  const resolvedCount = reports.filter(
    (report) => statusById[report.id] === "Resolved",
  ).length;
  const resolutionRate = reports.length
    ? Math.round((resolvedCount / reports.length) * 100)
    : 0;

  function updateStatus(reportId, status) {
    setStatusById((currentStatuses) => ({
      ...currentStatuses,
      [reportId]: status,
    }));
  }

  return (
    <section className="mx-auto w-full max-w-7xl space-y-7">
      <header>
        <p className="text-sm font-semibold uppercase tracking-wide text-emerald-700">
          CivicGuard staff
        </p>
        <h1 className="mt-1 text-2xl font-bold tracking-tight text-slate-900 sm:text-3xl">
          Admin Dashboard
        </h1>
        <p className="mt-2 text-sm leading-6 text-slate-600">
          Monitor incoming issues and track their resolution status.
        </p>
      </header>

      <div className="grid grid-cols-1 gap-4 sm:grid-cols-3">
        <SummaryCard
          accent="text-slate-900"
          detail="Across all categories"
          label="Total reported issues"
          value={reports.length}
        />
        <SummaryCard
          accent="text-red-700"
          detail="Require urgent attention"
          label="Critical issues"
          value={criticalCount}
        />
        <SummaryCard
          accent="text-green-700"
          detail={`${resolvedCount} of ${reports.length} reports resolved`}
          label="Resolution rate"
          value={`${resolutionRate}%`}
        />
      </div>

      <section className="overflow-hidden rounded-xl border border-slate-200 bg-white shadow-sm">
        <div className="flex flex-col gap-1 border-b border-slate-200 px-5 py-4 sm:flex-row sm:items-center sm:justify-between">
          <h2 className="font-semibold text-slate-900">Submitted issues</h2>
          <p className="text-xs text-slate-500">
            Status changes are temporary and reset when this page reloads.
          </p>
        </div>

        {loading ? (
          <p aria-live="polite" className="p-6 text-sm text-slate-600">
            Loading reports…
          </p>
        ) : error ? (
          <p className="p-6 text-sm text-red-700" role="alert">
            {error} Make sure the CivicGuard API is running.
          </p>
        ) : sortedReports.length === 0 ? (
          <p className="p-8 text-center text-sm text-slate-500">
            No reports have been submitted yet.
          </p>
        ) : (
          <div className="overflow-x-auto">
            <table className="min-w-full divide-y divide-slate-200 text-left">
              <thead className="bg-slate-50">
                <tr>
                  <th className="px-5 py-3 text-xs font-semibold uppercase tracking-wide text-slate-500">
                    Issue
                  </th>
                  <th className="px-5 py-3 text-xs font-semibold uppercase tracking-wide text-slate-500">
                    Urgency
                  </th>
                  <th className="px-5 py-3 text-xs font-semibold uppercase tracking-wide text-slate-500">
                    Severity
                  </th>
                  <th className="px-5 py-3 text-xs font-semibold uppercase tracking-wide text-slate-500">
                    Submitted
                  </th>
                  <th className="px-5 py-3 text-xs font-semibold uppercase tracking-wide text-slate-500">
                    Status
                  </th>
                  <th className="px-5 py-3 text-xs font-semibold uppercase tracking-wide text-slate-500">
                    Update status
                  </th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-100">
                {sortedReports.map((report) => {
                  const urgency = report.urgencyLevel.toLowerCase();
                  const currentStatus = statusById[report.id] ?? report.status;

                  return (
                    <tr className="align-top" key={report.id}>
                      <td className="max-w-sm px-5 py-4">
                        <p className="font-medium text-slate-900">{report.title}</p>
                        <p className="mt-1 text-xs text-slate-500">
                          {report.category}
                        </p>
                        <p className="mt-2 line-clamp-2 text-sm leading-5 text-slate-600">
                          {report.description}
                        </p>
                      </td>
                      <td className="whitespace-nowrap px-5 py-4">
                        <span
                          className={`inline-flex rounded-full px-2.5 py-1 text-xs font-semibold capitalize ring-1 ring-inset ${urgencyStyles[urgency] ?? "bg-slate-100 text-slate-700 ring-slate-600/20"}`}
                        >
                          {report.urgencyLevel}
                        </span>
                      </td>
                      <td className="whitespace-nowrap px-5 py-4 text-sm font-semibold text-slate-700">
                        {report.severityScore === null
                          ? "Not rated"
                          : `${report.severityScore} / 5`}
                      </td>
                      <td className="whitespace-nowrap px-5 py-4 text-sm text-slate-600">
                        {formatTimestamp(report.timestamp)}
                      </td>
                      <td className="whitespace-nowrap px-5 py-4">
                        <span
                          className={`inline-flex rounded-full px-2.5 py-1 text-xs font-semibold ${statusStyles[currentStatus]}`}
                        >
                          {currentStatus}
                        </span>
                      </td>
                      <td className="px-5 py-4">
                        <div aria-label={`Set status for ${report.title}`} className="flex flex-wrap gap-1.5">
                          {statuses.map((status) => (
                            <button
                              aria-pressed={currentStatus === status}
                              className={`rounded-md border px-2 py-1 text-xs font-medium transition focus:outline-none focus:ring-2 focus:ring-emerald-600/40 ${
                                currentStatus === status
                                  ? "border-emerald-700 bg-emerald-700 text-white"
                                  : "border-slate-200 bg-white text-slate-600 hover:bg-slate-50"
                              }`}
                              key={status}
                              onClick={() => updateStatus(report.id, status)}
                              type="button"
                            >
                              {status}
                            </button>
                          ))}
                        </div>
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
        )}
      </section>
    </section>
  );
}

