import { readFile, rename, unlink, writeFile } from "node:fs/promises";
import { fileURLToPath } from "node:url";

const reportsFile = fileURLToPath(new URL("../reports.json", import.meta.url));
const temporaryFile = `${reportsFile}.tmp`;

let reports = [];
let writeQueue = Promise.resolve();

async function writeReportsAtomically(nextReports) {
  const serializedReports = `${JSON.stringify(nextReports, null, 2)}\n`;

  try {
    await writeFile(temporaryFile, serializedReports, {
      encoding: "utf8",
      mode: 0o600,
    });
    await rename(temporaryFile, reportsFile);
  } catch (error) {
    await unlink(temporaryFile).catch(() => {});
    throw error;
  }
}

async function initializeReportsFile() {
  let fileContents;

  try {
    fileContents = await readFile(reportsFile, "utf8");
  } catch (error) {
    if (error.code !== "ENOENT") throw error;
    reports = [];
    await writeReportsAtomically(reports);
    return;
  }

  const savedReports = JSON.parse(fileContents);
  if (!Array.isArray(savedReports)) {
    throw new TypeError("backend/reports.json must contain a JSON array.");
  }

  reports = savedReports;
}

await initializeReportsFile();

function clone(value) {
  return structuredClone(value);
}

function enqueueWrite(transform) {
  const operation = writeQueue.catch(() => {}).then(async () => {
    const nextReports = transform(reports);
    if (nextReports === null) return null;

    await writeReportsAtomically(nextReports);
    reports = nextReports;
    return nextReports;
  });

  writeQueue = operation;
  return operation;
}

export async function getReports() {
  await writeQueue.catch(() => {});
  return clone(reports);
}

export async function saveReport(newReportData) {
  if (!newReportData || typeof newReportData !== "object" || Array.isArray(newReportData)) {
    throw new TypeError("A report object is required.");
  }

  const reportToSave = clone(newReportData);
  await enqueueWrite((currentReports) => [...currentReports, reportToSave]);
  return clone(reportToSave);
}

export async function updateReportStatus(id, status) {
  if (typeof id !== "string" || !id.trim()) {
    throw new TypeError("A report ID is required.");
  }
  if (typeof status !== "string" || !status.trim()) {
    throw new TypeError("A non-empty report status is required.");
  }

  const updatedReports = await enqueueWrite((currentReports) => {
    const reportIndex = currentReports.findIndex((report) => report.id === id);
    if (reportIndex === -1) return null;

    return currentReports.map((report, index) =>
      index === reportIndex ? { ...report, status: status.trim() } : report,
    );
  });

  if (updatedReports === null) return null;
  return clone(updatedReports.find((report) => report.id === id));
}

import { randomUUID } from "node:crypto";
import cors from "cors";
import dotenv from "dotenv";
import express from "express";
import multer from "multer";
import {
  getReports,
  saveReport,
  updateReportStatus,
} from "./services/db.js";
import { analyzeIssueReport } from "./services/geminiService.js";

dotenv.config();

const app = express();
const MAX_IMAGE_SIZE_BYTES = 10 * 1024 * 1024;

const upload = multer({
  storage: multer.memoryStorage(),
  limits: {
    fileSize: MAX_IMAGE_SIZE_BYTES,
    files: 1,
  },
  fileFilter(_request, file, callback) {
    if (!file.mimetype.startsWith("image/")) {
      callback(new Error("Uploaded file must be an image."));
      return;
    }

    callback(null, true);
  },
});

app.use(cors());
app.use(express.json({ limit: "1mb" }));

app.post("/api/reports", upload.single("image"), async (request, response, next) => {
  try {
    const description = request.body?.description;
    if (typeof description !== "string" || description.trim().length === 0) {
      console.error("[POST /api/reports] Validation failed: description is required.");
      response.status(400).json({ error: "A non-empty description is required." });
      return;
    }

    const selectedCategory =
      typeof request.body?.category === "string" ? request.body.category.trim() : "";
    const customCategory =
      typeof request.body?.customCategory === "string"
        ? request.body.customCategory.trim()
        : "";

    if (selectedCategory === "Other" && customCategory.length < 2) {
      console.error("[POST /api/reports] Validation failed: custom category is required for Other.");
      response.status(400).json({ error: "Enter a custom category when selecting Other." });
      return;
    }

    const normalizedDescription = description.trim();
    const analysis = await analyzeIssueReport(
      normalizedDescription,
      request.file ?? null,
    );

    if (analysis == null) {
      throw new Error("Issue analysis returned no result.");
    }

    const report = {
      id: randomUUID(),
      timestamp: new Date().toISOString(),
      title:
        typeof request.body?.title === "string" && request.body.title.trim()
          ? request.body.title.trim()
          : analysis.summary,
      category:
        selectedCategory === "Other"
          ? customCategory
          : selectedCategory || analysis.category,
      description: normalizedDescription,
      analysis,
      image: request.file
        ? {
            originalName: request.file.originalname,
            mimeType: request.file.mimetype,
            size: request.file.size,
          }
        : null,
    };

    await saveReport(report);
    response.status(201).json(report);
  } catch (error) {
    console.error("[POST /api/reports] Failed to analyze or save report:", error);
    next(error);
  }
});

app.get("/api/reports", async (_request, response, next) => {
  try {
    response.json(await getReports());
  } catch (error) {
    next(error);
  }
});

app.patch("/api/reports/:id/status", async (request, response, next) => {
  try {
    const { status } = request.body ?? {};
    if (!status || !["Pending", "In Progress", "Resolved"].includes(status)) {
      response.status(400).json({
        error: "Status must be Pending, In Progress, or Resolved.",
      });
      return;
    }

    const report = await updateReportStatus(request.params.id, status);
    if (!report) {
      response.status(404).json({ error: "Report not found." });
      return;
    }

    response.json(report);
  } catch (error) {
    next(error);
  }
});

app.use((_request, response) => {
  response.status(404).json({ error: "Route not found." });
});

app.use((error, _request, response, _next) => {
  console.error("CivicGuard request error:", error);

  if (error instanceof multer.MulterError) {
    const status = error.code === "LIMIT_FILE_SIZE" ? 413 : 400;
    response.status(status).json({ error: error.message });
    return;
  }

  if (error instanceof SyntaxError && "body" in error) {
    response.status(400).json({ error: "Request body contains invalid JSON." });
    return;
  }

  if (error.message === "Uploaded file must be an image.") {
    response.status(400).json({ error: error.message });
    return;
  }

  const isMissingApiKey =
    typeof error.message === "string" &&
    error.message.includes("GEMINI_API_KEY is not configured");
  const status = isMissingApiKey ? 503 : 500;
  const message =
    process.env.NODE_ENV === "production"
      ? "An unexpected server error occurred."
      : error.message || "An unexpected server error occurred.";

  response.status(status).json({ error: message });
});

const port = Number.parseInt(process.env.PORT ?? "5000", 10);
if (!Number.isInteger(port) || port < 1 || port > 65535) {
  throw new Error("PORT must be an integer between 1 and 65535.");
}

async function startServer() {
  try {
    await getReports();
    app.listen(port, () => {
      console.log(`CivicGuard API listening on port ${port}`);
    });
  } catch (error) {
    console.error("Failed to load persisted CivicGuard reports:", error);
    process.exitCode = 1;
  }
}

startServer();

export default app;

const REPORTS_URL = "http://localhost:5000/api/reports";

export async function getReports() {
  try {
    const response = await fetch(REPORTS_URL);
    if (!response.ok) {
      const details = await response.json().catch(() => null);
      throw new Error(
        details?.error ?? `The reports request failed with status ${response.status}.`,
      );
    }

    return await response.json();
  } catch (error) {
    const message = error instanceof Error ? error.message : "Unknown network error.";
    console.error("[CivicGuard API] Failed to fetch reports:", error);
    throw new Error(`Unable to get reports: ${message}`, { cause: error });
  }
}

export async function createReport(formData) {
  try {
    const response = await fetch(REPORTS_URL, {
      method: "POST",
      body: formData,
    });
    if (!response.ok) {
      const details = await response.json().catch(() => null);
      throw new Error(
        details?.error ?? `The report request failed with status ${response.status}.`,
      );
    }

    return await response.json();
  } catch (error) {
    const message = error instanceof Error ? error.message : "Unknown network error.";
    console.error("[CivicGuard API] Failed to create report:", error);
    throw new Error(`Unable to create report: ${message}`, { cause: error });
  }
}

export async function updateReportStatus(id, status) {
  try {
    const response = await fetch(
      `${REPORTS_URL}/${encodeURIComponent(id)}/status`,
      {
        method: "PATCH",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ status }),
      },
    );
    if (!response.ok) {
      const details = await response.json().catch(() => null);
      throw new Error(
        details?.error ?? `The status update failed with status ${response.status}.`,
      );
    }

    return await response.json();
  } catch (error) {
    const message = error instanceof Error ? error.message : "Unknown network error.";
    console.error("[CivicGuard API] Failed to update report status:", error);
    throw new Error(`Unable to update report status: ${message}`, { cause: error });
  }
}

import { useEffect, useMemo, useState } from "react";
import { updateReportStatus as saveReportStatus } from "../services/api.js";

const API_URL = "http://localhost:5000/api/reports";
const statuses = ["Pending", "In Progress", "Resolved"];
const urgencyOrder = { critical: 4, high: 3, medium: 2, low: 1 };

const urgencyStyles = {
  critical: "border-alert/30 bg-alert/10 text-alert",
  high: "border-amber-400/25 bg-amber-400/10 text-amber-300",
  medium: "border-yellow-400/25 bg-yellow-400/10 text-yellow-300",
  low: "border-mint/25 bg-mint/10 text-mint",
};

const statusStyles = {
  Pending: "bg-yellow-400/10 text-yellow-300",
  "In Progress": "bg-cyan/10 text-cyan",
  Resolved: "bg-mint/10 text-mint",
};

function normalizeReport(report, index) {
  const analysis =
    report.analysis && typeof report.analysis === "object" ? report.analysis : {};
  const severityValue =
    report.severityScore ??
    report.severity_score ??
    analysis.severityScore ??
    analysis.severity_score ??
    analysis.severity;
  const severityNumber = Number(severityValue);
  const severityScore =
    Number.isFinite(severityNumber) && severityNumber >= 1 && severityNumber <= 5
      ? Math.round(severityNumber)
      : null;
  const urgencyLevel = String(
    report.urgencyLevel ??
      report.urgency ??
      analysis.urgencyLevel ??
      analysis.urgency ??
      "Low",
  );
  const category = String(report.category ?? analysis.category ?? "Uncategorized");

  return {
    id: String(report.id ?? `report-${index}`),
    title: String(
      report.title ?? analysis.title ?? analysis.issueTitle ?? `${category} report`,
    ),
    category,
    description: String(
      report.description ??
        analysis.summary ??
        analysis.description ??
        "No description provided.",
    ),
    urgencyLevel,
    severityScore,
    timestamp: report.timestamp ?? report.createdAt ?? report.created_at,
    status: statuses.includes(report.status) ? report.status : "Pending",
  };
}

function formatTimestamp(timestamp) {
  if (!timestamp) return "—";
  const date = new Date(timestamp);
  if (Number.isNaN(date.getTime())) return "—";

  return new Intl.DateTimeFormat(undefined, {
    dateStyle: "medium",
    timeStyle: "short",
  }).format(date);
}

function SummaryCard({ label, value, detail, accent }) {
  return (
    <article className="rounded-xl border border-white/[0.06] bg-panel p-5 shadow-lg">
      <p className="font-mono text-[10px] uppercase tracking-wider text-muted">{label}</p>
      <p className={`mt-2 font-display text-3xl font-bold tracking-tight ${accent}`}>{value}</p>
      <p className="mt-1 text-xs text-muted">{detail}</p>
    </article>
  );
}

export default function AdminDashboard() {
  const [reports, setReports] = useState([]);
  const [statusById, setStatusById] = useState({});
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  const [statusError, setStatusError] = useState("");
  const [updatingReportId, setUpdatingReportId] = useState(null);

  useEffect(() => {
    const controller = new AbortController();

    async function loadReports() {
      try {
        const response = await fetch(API_URL, { signal: controller.signal });
        if (!response.ok) {
          throw new Error(`Could not load reports (${response.status}).`);
        }

        const data = await response.json();
        if (!Array.isArray(data)) {
          throw new Error("The reports response was not a list.");
        }

        const normalizedReports = data.map(normalizeReport);
        setReports(normalizedReports);
        setStatusById(
          Object.fromEntries(
            normalizedReports.map((report) => [report.id, report.status]),
          ),
        );
      } catch (loadError) {
        if (loadError.name !== "AbortError") {
          setError(loadError.message || "Could not load reports.");
        }
      } finally {
        if (!controller.signal.aborted) setLoading(false);
      }
    }

    loadReports();
    return () => controller.abort();
  }, []);

  const sortedReports = useMemo(
    () =>
      [...reports].sort((first, second) => {
        const firstUrgency =
          urgencyOrder[first.urgencyLevel.toLowerCase()] ?? 0;
        const secondUrgency =
          urgencyOrder[second.urgencyLevel.toLowerCase()] ?? 0;

        return (
          secondUrgency - firstUrgency ||
          (second.severityScore ?? 0) - (first.severityScore ?? 0)
        );
      }),
    [reports],
  );

  const criticalCount = reports.filter(
    (report) => report.urgencyLevel.toLowerCase() === "critical",
  ).length;
  const resolvedCount = reports.filter(
    (report) => statusById[report.id] === "Resolved",
  ).length;
  const resolutionRate = reports.length
    ? Math.round((resolvedCount / reports.length) * 100)
    : 0;

  async function updateStatus(reportId, status) {
    setUpdatingReportId(reportId);
    setStatusError("");

    try {
      const updatedReport = await saveReportStatus(reportId, status);
      setStatusById((currentStatuses) => ({
        ...currentStatuses,
        [reportId]: updatedReport.status,
      }));
    } catch (updateError) {
      setStatusError(updateError.message || "Could not update report status.");
    } finally {
      setUpdatingReportId(null);
    }
  }

  return (
    <section className="mx-auto w-full max-w-[1720px] space-y-7">
      <header>
        <p className="font-mono text-[10px] font-semibold uppercase tracking-[0.16em] text-cyan">
          CivicGuard staff / operations
        </p>
        <h1 className="mt-1 font-display text-2xl font-bold tracking-tight text-ink sm:text-3xl">
          Municipal Incident Ops
        </h1>
        <p className="mt-2 text-sm leading-6 text-muted">
          Monitor incoming issues and track their resolution status.
        </p>
      </header>

      {statusError && (
        <p className="rounded border border-alert/20 bg-alert/10 px-4 py-3 text-sm text-alert" role="alert">
          {statusError}
        </p>
      )}

      <div className="grid grid-cols-1 gap-4 sm:grid-cols-3">
        <SummaryCard
          accent="text-cyan"
          detail="Across all categories"
          label="Total reported issues"
          value={reports.length}
        />
        <SummaryCard
          accent="text-alert"
          detail="Require urgent attention"
          label="Critical issues"
          value={criticalCount}
        />
        <SummaryCard
          accent="text-mint"
          detail={`${resolvedCount} of ${reports.length} reports resolved`}
          label="Resolution rate"
          value={`${resolutionRate}%`}
        />
      </div>

      <section className="overflow-hidden rounded-xl border border-white/[0.06] bg-panel shadow-xl">
        <div className="flex flex-col gap-1 border-b border-white/[0.06] px-5 py-4 sm:flex-row sm:items-center sm:justify-between">
          <h2 className="font-display font-semibold text-ink">Submitted incidents</h2>
          <p className="font-mono text-[9px] text-muted">
            Status changes are saved automatically.
          </p>
        </div>

        {loading ? (
          <p aria-live="polite" className="p-6 text-sm text-muted">
            Loading incident data…
          </p>
        ) : error ? (
          <p className="p-6 text-sm text-alert" role="alert">
            {error} Make sure the CivicGuard API is running.
          </p>
        ) : sortedReports.length === 0 ? (
          <p className="p-8 text-center text-sm text-muted">
            No reports have been submitted yet.
          </p>
        ) : (
          <div className="overflow-x-auto">
            <table className="min-w-full divide-y divide-white/[0.06] text-left">
              <thead className="bg-deep/60">
                <tr>
                  <th className="px-5 py-3 font-mono text-[9px] font-semibold uppercase tracking-wide text-muted">
                    Issue
                  </th>
                  <th className="px-5 py-3 font-mono text-[9px] font-semibold uppercase tracking-wide text-muted">
                    Urgency
                  </th>
                  <th className="px-5 py-3 font-mono text-[9px] font-semibold uppercase tracking-wide text-muted">
                    Severity
                  </th>
                  <th className="px-5 py-3 font-mono text-[9px] font-semibold uppercase tracking-wide text-muted">
                    Submitted
                  </th>
                  <th className="px-5 py-3 font-mono text-[9px] font-semibold uppercase tracking-wide text-muted">
                    Status
                  </th>
                  <th className="px-5 py-3 font-mono text-[9px] font-semibold uppercase tracking-wide text-muted">
                    Update status
                  </th>
                </tr>
              </thead>
              <tbody className="divide-y divide-white/[0.04]">
                {sortedReports.map((report) => {
                  const urgency = report.urgencyLevel.toLowerCase();
                  const currentStatus = statusById[report.id] ?? report.status;
                  const isUpdating = updatingReportId === report.id;

                  return (
                    <tr className="align-top" key={report.id}>
                      <td className="max-w-sm px-5 py-4">
                        <p className="font-semibold text-ink">{report.title}</p>
                        <p className="mt-1 font-mono text-[9px] text-cyan">
                          {report.category}
                        </p>
                        <p className="mt-2 line-clamp-2 text-xs leading-5 text-muted">
                          {report.description}
                        </p>
                      </td>
                      <td className="whitespace-nowrap px-5 py-4">
                        <span
                          className={`inline-flex rounded-full border px-2.5 py-1 font-mono text-[9px] font-semibold uppercase ring-1 ring-inset ${urgencyStyles[urgency] ?? "border-white/10 bg-panel-hover text-muted"}`}
                        >
                          {report.urgencyLevel}
                        </span>
                      </td>
                      <td className="whitespace-nowrap px-5 py-4 font-mono text-xs font-semibold text-ink">
                        {report.severityScore === null
                          ? "Not rated"
                          : `${report.severityScore} / 5`}
                      </td>
                      <td className="whitespace-nowrap px-5 py-4 font-mono text-[9px] text-muted">
                        {formatTimestamp(report.timestamp)}
                      </td>
                      <td className="whitespace-nowrap px-5 py-4">
                        <span
                          className={`inline-flex rounded-full px-2.5 py-1 font-mono text-[9px] font-semibold ${statusStyles[currentStatus]}`}
                        >
                          {currentStatus}
                        </span>
                      </td>
                      <td className="px-5 py-4">
                        <div aria-label={`Set status for ${report.title}`} className="flex flex-wrap gap-1.5">
                          {statuses.map((status) => (
                            <button
                              aria-pressed={currentStatus === status}
                              className={`rounded border px-2 py-1 font-mono text-[9px] font-medium transition focus:outline-none focus:ring-2 focus:ring-cyan/40 disabled:cursor-wait disabled:opacity-50 ${
                                currentStatus === status
                                  ? "border-cyan bg-cyan text-[#06202a]"
                                  : "border-white/10 bg-panel-raised text-muted hover:border-cyan/30 hover:text-ink"
                              }`}
                              disabled={isUpdating}
                              key={status}
                              onClick={() => updateStatus(report.id, status)}
                              type="button"
                            >
                              {status}
                            </button>
                          ))}
                        </div>
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
        )}
      </section>
    </section>
  );
}

