import { randomBytes } from "node:crypto";
import { readFile, writeFile } from "node:fs/promises";
import { fileURLToPath } from "node:url";

const localSecretFile = fileURLToPath(new URL("../.jwt-secret", import.meta.url));
let localSecretPromise;

async function readLocalSecret() {
  const secret = (await readFile(localSecretFile, "utf8")).trim();
  if (secret.length < 32) {
    throw new Error("The local JWT secret is invalid. Remove backend/.jwt-secret to regenerate it.");
  }
  return secret;
}

async function loadOrCreateLocalSecret() {
  try {
    return await readLocalSecret();
  } catch (error) {
    if (error.code !== "ENOENT") throw error;
  }

  const secret = randomBytes(64).toString("base64url");
  try {
    await writeFile(localSecretFile, `${secret}\n`, {
      encoding: "utf8",
      flag: "wx",
      mode: 0o600,
    });
    return secret;
  } catch (error) {
    if (error.code !== "EEXIST") throw error;
    return readLocalSecret();
  }
}

export async function getJwtSecret() {
  const configuredSecret = process.env.JWT_SECRET;
  if (configuredSecret) {
    if (configuredSecret.length < 32) {
      throw new Error("JWT_SECRET must be at least 32 characters long.");
    }
    return configuredSecret;
  }

  if (process.env.NODE_ENV === "production") {
    throw new Error("JWT_SECRET must be configured in production.");
  }

  localSecretPromise ??= loadOrCreateLocalSecret();
  return localSecretPromise;
}

import { readFile, rename, unlink, writeFile } from "node:fs/promises";
import { fileURLToPath } from "node:url";

const reportsFile = fileURLToPath(new URL("../reports.json", import.meta.url));
const temporaryFile = `${reportsFile}.tmp`;
const usersFile = fileURLToPath(new URL("../users.json", import.meta.url));
const temporaryUsersFile = `${usersFile}.tmp`;

let reports = [];
let writeQueue = Promise.resolve();
let users = [];
let usersWriteQueue = Promise.resolve();

async function writeReportsAtomically(nextReports) {
  const serializedReports = `${JSON.stringify(nextReports, null, 2)}\n`;

  try {
    await writeFile(temporaryFile, serializedReports, {
      encoding: "utf8",
      mode: 0o600,
    });
    await rename(temporaryFile, reportsFile);
  } catch (error) {
    await unlink(temporaryFile).catch(() => {});
    throw error;
  }
}

async function initializeReportsFile() {
  let fileContents;

  try {
    fileContents = await readFile(reportsFile, "utf8");
  } catch (error) {
    if (error.code !== "ENOENT") throw error;
    reports = [];
    await writeReportsAtomically(reports);
    return;
  }

  const savedReports = JSON.parse(fileContents);
  if (!Array.isArray(savedReports)) {
    throw new TypeError("backend/reports.json must contain a JSON array.");
  }

  reports = savedReports;
}

async function writeUsersAtomically(nextUsers) {
  const serializedUsers = `${JSON.stringify(nextUsers, null, 2)}\n`;

  try {
    await writeFile(temporaryUsersFile, serializedUsers, {
      encoding: "utf8",
      mode: 0o600,
    });
    await rename(temporaryUsersFile, usersFile);
  } catch (error) {
    await unlink(temporaryUsersFile).catch(() => {});
    throw error;
  }
}

async function initializeUsersFile() {
  let fileContents;

  try {
    fileContents = await readFile(usersFile, "utf8");
  } catch (error) {
    if (error.code !== "ENOENT") throw error;
    users = [];
    await writeUsersAtomically(users);
    return;
  }

  const savedUsers = JSON.parse(fileContents);
  if (!Array.isArray(savedUsers)) {
    throw new TypeError("backend/users.json must contain a JSON array.");
  }

  users = savedUsers;
}

await Promise.all([initializeReportsFile(), initializeUsersFile()]);

function clone(value) {
  return structuredClone(value);
}

function enqueueWrite(transform) {
  const operation = writeQueue.catch(() => {}).then(async () => {
    const nextReports = transform(reports);
    if (nextReports === null) return null;

    await writeReportsAtomically(nextReports);
    reports = nextReports;
    return nextReports;
  });

  writeQueue = operation;
  return operation;
}

function enqueueUserWrite(transform) {
  const operation = usersWriteQueue.catch(() => {}).then(async () => {
    const nextUsers = transform(users);
    if (nextUsers === null) return null;

    await writeUsersAtomically(nextUsers);
    users = nextUsers;
    return nextUsers;
  });

  usersWriteQueue = operation;
  return operation;
}

export async function getReports() {
  await writeQueue.catch(() => {});
  return clone(reports);
}

export async function getUserByEmail(email) {
  await usersWriteQueue.catch(() => {});
  const normalizedEmail = String(email).trim().toLowerCase();
  const user = users.find((candidate) => candidate.email === normalizedEmail);
  return user ? clone(user) : null;
}

export async function saveUser(newUserData) {
  if (!newUserData || typeof newUserData !== "object" || Array.isArray(newUserData)) {
    throw new TypeError("A user object is required.");
  }

  const userToSave = clone(newUserData);
  if (typeof userToSave.email !== "string" || !userToSave.email.trim()) {
    throw new TypeError("A user email is required.");
  }
  userToSave.email = userToSave.email.trim().toLowerCase();

  await enqueueUserWrite((currentUsers) => {
    if (currentUsers.some((user) => user.email === userToSave.email)) {
      const error = new Error("An account with this email already exists.");
      error.code = "DUPLICATE_EMAIL";
      throw error;
    }
    return [...currentUsers, userToSave];
  });

  return clone(userToSave);
}

export async function saveReport(newReportData) {
  if (!newReportData || typeof newReportData !== "object" || Array.isArray(newReportData)) {
    throw new TypeError("A report object is required.");
  }

  const reportToSave = clone(newReportData);
  await enqueueWrite((currentReports) => [...currentReports, reportToSave]);
  return clone(reportToSave);
}

export async function updateReportStatus(id, status) {
  if (typeof id !== "string" || !id.trim()) {
    throw new TypeError("A report ID is required.");
  }
  if (typeof status !== "string" || !status.trim()) {
    throw new TypeError("A non-empty report status is required.");
  }

  const updatedReports = await enqueueWrite((currentReports) => {
    const reportIndex = currentReports.findIndex((report) => report.id === id);
    if (reportIndex === -1) return null;

    return currentReports.map((report, index) =>
      index === reportIndex ? { ...report, status: status.trim() } : report,
    );
  });

  if (updatedReports === null) return null;
  return clone(updatedReports.find((report) => report.id === id));
}

export async function deleteReport(id) {
  if (typeof id !== "string" || !id.trim()) {
    throw new TypeError("A report ID is required.");
  }

  let deletedReport = null;
  const updatedReports = await enqueueWrite((currentReports) => {
    deletedReport = currentReports.find((report) => report.id === id) ?? null;
    if (!deletedReport) return null;
    return currentReports.filter((report) => report.id !== id);
  });

  return updatedReports === null ? null : clone(deletedReport);
}

import jwt from "jsonwebtoken";
import { getJwtSecret } from "../services/jwtSecret.js";

export async function verifyToken(request, response, next) {
  const authorization = request.get("authorization") ?? "";
  const [scheme, token] = authorization.split(/\s+/);

  if (scheme !== "Bearer" || !token) {
    response.status(401).json({ error: "A Bearer token is required." });
    return;
  }

  let secret;
  try {
    secret = await getJwtSecret();
  } catch (error) {
    next(error);
    return;
  }

  try {
    const claims = jwt.verify(token, secret, { issuer: "civicguard" });
    if (
      typeof claims !== "object" ||
      typeof claims.sub !== "string" ||
      typeof claims.email !== "string" ||
      !["citizen", "authority"].includes(claims.role)
    ) {
      response.status(401).json({ error: "The authentication token is invalid." });
      return;
    }

    request.user = {
      id: claims.sub,
      email: claims.email,
      role: claims.role,
    };
    next();
  } catch {
    response.status(401).json({ error: "The authentication token is invalid or expired." });
  }
}

export function requireAuthority(request, response, next) {
  if (request.user?.role !== "authority") {
    response.status(403).json({ error: "Authority access is required for this action." });
    return;
  }

  next();
}

import { randomUUID } from "node:crypto";
import bcrypt from "bcryptjs";
import express from "express";
import jwt from "jsonwebtoken";
import { getUserByEmail, saveUser } from "../services/db.js";
import { getJwtSecret } from "../services/jwtSecret.js";

const router = express.Router();
const AUTHORITY_INVITE_CODE = "[REDACTED_AUTHORITY_INVITE_CODE]";
const PASSWORD_MIN_LENGTH = 8;

function normalizeRole(role) {
  const normalized = typeof role === "string" ? role.trim().toLowerCase() : "";
  if (normalized === "citizen") return "citizen";
  if (normalized === "authority" || normalized === "authority member") {
    return "authority";
  }
  return null;
}

function isValidEmail(email) {
  return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
}

function hasGovernmentDomain(email) {
  const domain = email.split("@")[1]?.toLowerCase() ?? "";
  return domain.endsWith(".gov");
}

function createAuthResponse(user, secret) {
  const token = jwt.sign(
    { email: user.email, role: user.role },
    secret,
    {
      subject: user.id,
      issuer: "civicguard",
      expiresIn: "8h",
    },
  );

  return {
    token,
    user: {
      id: user.id,
      name: user.name,
      email: user.email,
      role: user.role,
    },
  };
}

router.post("/register", async (request, response, next) => {
  try {
    const { name, email, password, inviteCode } = request.body ?? {};
    const role = normalizeRole(request.body?.role);

    if (
      typeof name !== "string" ||
      !name.trim() ||
      typeof email !== "string" ||
      !isValidEmail(email.trim()) ||
      typeof password !== "string" ||
      password.length < PASSWORD_MIN_LENGTH ||
      Buffer.byteLength(password, "utf8") > 72 ||
      !role
    ) {
      response.status(400).json({
        error: "Provide a name, valid email, password (8–72 bytes), and a valid role.",
      });
      return;
    }

    const normalizedEmail = email.trim().toLowerCase();
    if (
      role === "authority" &&
      inviteCode !== AUTHORITY_INVITE_CODE &&
      !hasGovernmentDomain(normalizedEmail)
    ) {
      response.status(403).json({
        error: "Authority registration requires the official invite code or a .gov email address.",
      });
      return;
    }

    const existingUser = await getUserByEmail(normalizedEmail);
    if (existingUser) {
      response.status(409).json({ error: "An account with this email already exists." });
      return;
    }

    const passwordHash = await bcrypt.hash(password, 12);
    const user = await saveUser({
      id: randomUUID(),
      name: name.trim(),
      email: normalizedEmail,
      passwordHash,
      role,
      createdAt: new Date().toISOString(),
    });

    response.status(201).json(createAuthResponse(user, await getJwtSecret()));
  } catch (error) {
    if (error.code === "DUPLICATE_EMAIL") {
      response.status(409).json({ error: "An account with this email already exists." });
      return;
    }
    next(error);
  }
});

router.post("/login", async (request, response, next) => {
  try {
    const { email, password } = request.body ?? {};
    if (typeof email !== "string" || typeof password !== "string") {
      response.status(400).json({ error: "Email and password are required." });
      return;
    }

    const user = await getUserByEmail(email.trim().toLowerCase());
    if (!user || !(await bcrypt.compare(password, user.passwordHash))) {
      response.status(401).json({ error: "Email or password is incorrect." });
      return;
    }

    response.json(createAuthResponse(user, await getJwtSecret()));
  } catch (error) {
    next(error);
  }
});

export default router;

import { randomUUID } from "node:crypto";
import bcrypt from "bcryptjs";
import express from "express";
import jwt from "jsonwebtoken";
import { getUserByEmail, saveUser } from "../services/db.js";
import { getJwtSecret } from "../services/jwtSecret.js";

const router = express.Router();
const AUTHORITY_INVITE_CODE = "[REDACTED_AUTHORITY_INVITE_CODE]";
const PASSWORD_MIN_LENGTH = 8;

function normalizeRole(role) {
  const normalized = typeof role === "string" ? role.trim().toLowerCase() : "";
  if (normalized === "citizen") return "citizen";
  if (normalized === "authority" || normalized === "authority member") {
    return "authority";
  }
  return null;
}

function isValidEmail(email) {
  return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
}

function hasGovernmentDomain(email) {
  const domain = email.split("@")[1]?.toLowerCase() ?? "";
  return domain.endsWith(".gov");
}

function createAuthResponse(user, secret) {
  const token = jwt.sign(
    { email: user.email, role: user.role },
    secret,
    {
      subject: user.id,
      issuer: "civicguard",
      expiresIn: "8h",
    },
  );

  return {
    token,
    user: {
      id: user.id,
      name: user.name,
      email: user.email,
      role: user.role,
    },
  };
}

router.post("/register", async (request, response, next) => {
  try {
    const { name, email, password, inviteCode } = request.body ?? {};
    const role = normalizeRole(request.body?.role);

    if (
      typeof name !== "string" ||
      !name.trim() ||
      typeof email !== "string" ||
      !isValidEmail(email.trim()) ||
      typeof password !== "string" ||
      password.length < PASSWORD_MIN_LENGTH ||
      Buffer.byteLength(password, "utf8") > 72 ||
      !role
    ) {
      response.status(400).json({
        error: "Provide a name, valid email, password (8–72 bytes), and a valid role.",
      });
      return;
    }

    const normalizedEmail = email.trim().toLowerCase();
    if (
      role === "authority" &&
      inviteCode !== AUTHORITY_INVITE_CODE &&
      !hasGovernmentDomain(normalizedEmail)
    ) {
      response.status(403).json({
        error: "Authority registration requires the official invite code or a .gov email address.",
      });
      return;
    }

    const existingUser = await getUserByEmail(normalizedEmail);
    if (existingUser) {
      response.status(409).json({ error: "An account with this email already exists." });
      return;
    }

    const secret = await getJwtSecret();
    const passwordHash = await bcrypt.hash(password, 12);
    const user = await saveUser({
      id: randomUUID(),
      name: name.trim(),
      email: normalizedEmail,
      passwordHash,
      role,
      createdAt: new Date().toISOString(),
    });

    response.status(201).json(createAuthResponse(user, secret));
  } catch (error) {
    if (error.code === "DUPLICATE_EMAIL") {
      response.status(409).json({ error: "An account with this email already exists." });
      return;
    }
    next(error);
  }
});

router.post("/login", async (request, response, next) => {
  try {
    const { email, password } = request.body ?? {};
    if (typeof email !== "string" || typeof password !== "string") {
      response.status(400).json({ error: "Email and password are required." });
      return;
    }

    const user = await getUserByEmail(email.trim().toLowerCase());
    if (!user || !(await bcrypt.compare(password, user.passwordHash))) {
      response.status(401).json({ error: "Email or password is incorrect." });
      return;
    }

    response.json(createAuthResponse(user, await getJwtSecret()));
  } catch (error) {
    next(error);
  }
});

export default router;

import { randomUUID } from "node:crypto";
import cors from "cors";
import dotenv from "dotenv";
import express from "express";
import multer from "multer";
import { requireAuthority, verifyToken } from "./middleware/auth.js";
import authRoutes from "./routes/auth.js";
import {
  deleteReport,
  getReports,
  saveReport,
  updateReportStatus,
} from "./services/db.js";
import { analyzeIssueReport } from "./services/geminiService.js";
import { getJwtSecret } from "./services/jwtSecret.js";

dotenv.config();

const app = express();
const MAX_IMAGE_SIZE_BYTES = 10 * 1024 * 1024;

const upload = multer({
  storage: multer.memoryStorage(),
  limits: {
    fileSize: MAX_IMAGE_SIZE_BYTES,
    files: 1,
  },
  fileFilter(_request, file, callback) {
    if (!file.mimetype.startsWith("image/")) {
      callback(new Error("Uploaded file must be an image."));
      return;
    }

    callback(null, true);
  },
});

app.use(cors());
app.use(express.json({ limit: "1mb" }));
app.use("/api/auth", authRoutes);

app.post("/api/reports", upload.single("image"), async (request, response, next) => {
  try {
    const description = request.body?.description;
    if (typeof description !== "string" || description.trim().length === 0) {
      console.error("[POST /api/reports] Validation failed: description is required.");
      response.status(400).json({ error: "A non-empty description is required." });
      return;
    }

    const selectedCategory =
      typeof request.body?.category === "string" ? request.body.category.trim() : "";
    const customCategory =
      typeof request.body?.customCategory === "string"
        ? request.body.customCategory.trim()
        : "";

    if (selectedCategory === "Other" && customCategory.length < 2) {
      console.error("[POST /api/reports] Validation failed: custom category is required for Other.");
      response.status(400).json({ error: "Enter a custom category when selecting Other." });
      return;
    }

    const normalizedDescription = description.trim();
    const analysis = await analyzeIssueReport(
      normalizedDescription,
      request.file ?? null,
    );

    if (analysis == null) {
      throw new Error("Issue analysis returned no result.");
    }

    const report = {
      id: randomUUID(),
      timestamp: new Date().toISOString(),
      title:
        typeof request.body?.title === "string" && request.body.title.trim()
          ? request.body.title.trim()
          : analysis.summary,
      category:
        selectedCategory === "Other"
          ? customCategory
          : selectedCategory || analysis.category,
      description: normalizedDescription,
      analysis,
      image: request.file
        ? {
            originalName: request.file.originalname,
            mimeType: request.file.mimetype,
            size: request.file.size,
          }
        : null,
    };

    await saveReport(report);
    response.status(201).json(report);
  } catch (error) {
    console.error("[POST /api/reports] Failed to analyze or save report:", error);
    next(error);
  }
});

app.get("/api/reports", async (_request, response, next) => {
  try {
    response.json(await getReports());
  } catch (error) {
    next(error);
  }
});

app.patch(
  "/api/reports/:id/status",
  verifyToken,
  requireAuthority,
  async (request, response, next) => {
  try {
    const { status } = request.body ?? {};
    if (!status || !["Pending", "In Progress", "Resolved"].includes(status)) {
      response.status(400).json({
        error: "Status must be Pending, In Progress, or Resolved.",
      });
      return;
    }

    const report = await updateReportStatus(request.params.id, status);
    if (!report) {
      response.status(404).json({ error: "Report not found." });
      return;
    }

    response.json(report);
  } catch (error) {
    next(error);
  }
  },
);

app.delete(
  "/api/reports/:id",
  verifyToken,
  requireAuthority,
  async (request, response, next) => {
    try {
      const report = await deleteReport(request.params.id);
      if (!report) {
        response.status(404).json({ error: "Report not found." });
        return;
      }

      response.json({ message: "Report deleted.", id: report.id });
    } catch (error) {
      next(error);
    }
  },
);

app.use((_request, response) => {
  response.status(404).json({ error: "Route not found." });
});

app.use((error, _request, response, _next) => {
  console.error("CivicGuard request error:", error);

  if (error instanceof multer.MulterError) {
    const status = error.code === "LIMIT_FILE_SIZE" ? 413 : 400;
    response.status(status).json({ error: error.message });
    return;
  }

  if (error instanceof SyntaxError && "body" in error) {
    response.status(400).json({ error: "Request body contains invalid JSON." });
    return;
  }

  if (error.message === "Uploaded file must be an image.") {
    response.status(400).json({ error: error.message });
    return;
  }

  const isMissingApiKey =
    typeof error.message === "string" &&
    error.message.includes("GEMINI_API_KEY is not configured");
  const status = isMissingApiKey ? 503 : 500;
  const message =
    process.env.NODE_ENV === "production"
      ? "An unexpected server error occurred."
      : error.message || "An unexpected server error occurred.";

  response.status(status).json({ error: message });
});

const port = Number.parseInt(process.env.PORT ?? "5000", 10);
if (!Number.isInteger(port) || port < 1 || port > 65535) {
  throw new Error("PORT must be an integer between 1 and 65535.");
}

async function startServer() {
  try {
    await getReports();
    await getJwtSecret();
    app.listen(port, () => {
      console.log(`CivicGuard API listening on port ${port}`);
    });
  } catch (error) {
    console.error("Failed to load persisted CivicGuard reports:", error);
    process.exitCode = 1;
  }
}

startServer();

export default app;

const REPORTS_URL = "http://localhost:5000/api/reports";
const API_URL = "http://localhost:5000/api";

async function postAuthRequest(path, credentials) {
  const response = await fetch(`${API_URL}/auth/${path}`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(credentials),
  });

  const result = await response.json().catch(() => ({}));
  if (!response.ok) {
    throw new Error(result.error ?? `Authentication failed (${response.status}).`);
  }

  return result;
}

export async function loginUser(credentials) {
  try {
    return await postAuthRequest("login", credentials);
  } catch (error) {
    console.error("[CivicGuard API] Login failed:", error);
    throw error;
  }
}

export async function registerUser(details) {
  try {
    return await postAuthRequest("register", details);
  } catch (error) {
    console.error("[CivicGuard API] Registration failed:", error);
    throw error;
  }
}

export async function getReports() {
  try {
    const response = await fetch(REPORTS_URL);
    if (!response.ok) {
      const details = await response.json().catch(() => null);
      throw new Error(
        details?.error ?? `The reports request failed with status ${response.status}.`,
      );
    }

    return await response.json();
  } catch (error) {
    const message = error instanceof Error ? error.message : "Unknown network error.";
    console.error("[CivicGuard API] Failed to fetch reports:", error);
    throw new Error(`Unable to get reports: ${message}`, { cause: error });
  }
}

export async function createReport(formData) {
  try {
    const response = await fetch(REPORTS_URL, {
      method: "POST",
      body: formData,
    });
    if (!response.ok) {
      const details = await response.json().catch(() => null);
      throw new Error(
        details?.error ?? `The report request failed with status ${response.status}.`,
      );
    }

    return await response.json();
  } catch (error) {
    const message = error instanceof Error ? error.message : "Unknown network error.";
    console.error("[CivicGuard API] Failed to create report:", error);
    throw new Error(`Unable to create report: ${message}`, { cause: error });
  }
}

export async function updateReportStatus(id, status, token) {
  try {
    const response = await fetch(
      `${REPORTS_URL}/${encodeURIComponent(id)}/status`,
      {
        method: "PATCH",
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${token}`,
        },
        body: JSON.stringify({ status }),
      },
    );
    if (!response.ok) {
      const details = await response.json().catch(() => null);
      throw new Error(
        details?.error ?? `The status update failed with status ${response.status}.`,
      );
    }

    return await response.json();
  } catch (error) {
    const message = error instanceof Error ? error.message : "Unknown network error.";
    console.error("[CivicGuard API] Failed to update report status:", error);
    throw new Error(`Unable to update report status: ${message}`, { cause: error });
  }
}

import { createContext, useCallback, useContext, useMemo, useState } from "react";
import { loginUser, registerUser } from "../services/api.js";

const STORAGE_KEY = "civicguard.auth";
const AuthContext = createContext(null);

function readStoredSession() {
  try {
    const stored = localStorage.getItem(STORAGE_KEY);
    if (!stored) return null;

    const session = JSON.parse(stored);
    if (
      typeof session.token !== "string" ||
      !session.user ||
      !["citizen", "authority"].includes(session.user.role)
    ) {
      localStorage.removeItem(STORAGE_KEY);
      return null;
    }

    return session;
  } catch {
    localStorage.removeItem(STORAGE_KEY);
    return null;
  }
}

export function AuthProvider({ children }) {
  const [session, setSession] = useState(readStoredSession);

  const persistSession = useCallback((nextSession) => {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(nextSession));
    setSession(nextSession);
    return nextSession.user;
  }, []);

  const login = useCallback(async (credentials) => {
    const result = await loginUser(credentials);
    return persistSession({ token: result.token, user: result.user });
  }, [persistSession]);

  const register = useCallback(async (details) => {
    const result = await registerUser(details);
    return persistSession({ token: result.token, user: result.user });
  }, [persistSession]);

  const logout = useCallback(() => {
    localStorage.removeItem(STORAGE_KEY);
    setSession(null);
  }, []);

  const value = useMemo(
    () => ({
      user: session?.user ?? null,
      token: session?.token ?? null,
      isAuthenticated: Boolean(session?.token),
      login,
      register,
      logout,
    }),
    [session, login, register, logout],
  );

  return <AuthContext.Provider value={value}>{children}</AuthContext.Provider>;
}

export function useAuth() {
  const context = useContext(AuthContext);
  if (!context) throw new Error("useAuth must be used within an AuthProvider.");
  return context;
}

import { useState } from "react";
import { useAuth } from "../context/AuthContext.jsx";

export default function LoginModal({ isOpen, onClose, onSuccess }) {
  const { login, register } = useAuth();
  const [mode, setMode] = useState("login");
  const [role, setRole] = useState("citizen");
  const [name, setName] = useState("");
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [inviteCode, setInviteCode] = useState("");
  const [error, setError] = useState("");
  const [isSubmitting, setIsSubmitting] = useState(false);

  if (!isOpen) return null;

  async function handleSubmit(event) {
    event.preventDefault();
    setError("");
    setIsSubmitting(true);

    try {
      const user = mode === "login"
        ? await login({ email, password })
        : await register({ name, email, password, role, inviteCode });
      onSuccess?.(user);
      onClose();
    } catch (submitError) {
      setError(submitError.message || "Authentication failed. Please try again.");
    } finally {
      setIsSubmitting(false);
    }
  }

  return (
    <div
      className="fixed inset-0 z-50 grid place-items-center overflow-y-auto bg-deep/80 p-4 backdrop-blur-sm"
      onMouseDown={(event) => {
        if (event.target === event.currentTarget) onClose();
      }}
    >
      <section
        aria-labelledby="auth-modal-title"
        aria-modal="true"
        className="my-8 w-full max-w-md overflow-hidden rounded-xl border border-white/10 bg-panel shadow-2xl shadow-black/40"
        role="dialog"
      >
        <div className="border-b border-white/[0.06] px-6 pb-5 pt-6">
          <div className="flex items-start justify-between gap-4">
            <div>
              <p className="font-mono text-[9px] font-semibold uppercase tracking-[0.16em] text-cyan">
                CivicGuard identity / secure access
              </p>
              <h2 className="mt-2 font-display text-2xl font-semibold text-ink" id="auth-modal-title">
                {mode === "login" ? "Welcome back" : "Create your account"}
              </h2>
              <p className="mt-1 text-sm text-muted">
                {mode === "login"
                  ? "Sign in to access your CivicGuard workspace."
                  : "Join your community’s incident response network."}
              </p>
            </div>
            <button
              aria-label="Close authentication dialog"
              className="rounded border border-white/10 bg-panel-raised px-2.5 py-1.5 font-mono text-xs text-muted hover:text-ink"
              onClick={onClose}
              type="button"
            >
              ×
            </button>
          </div>

          <div className="mt-5 inline-flex rounded-lg border border-white/[0.06] bg-deep p-1">
            {[
              { id: "login", label: "Sign in" },
              { id: "register", label: "Register" },
            ].map((item) => (
              <button
                aria-pressed={mode === item.id}
                className={`rounded px-4 py-2 font-mono text-[10px] font-semibold uppercase tracking-wide transition ${
                  mode === item.id ? "bg-cyan text-[#06202a]" : "text-muted hover:text-ink"
                }`}
                key={item.id}
                onClick={() => {
                  setMode(item.id);
                  setError("");
                }}
                type="button"
              >
                {item.label}
              </button>
            ))}
          </div>
        </div>

        <form className="space-y-4 px-6 py-5" onSubmit={handleSubmit}>
          {mode === "register" && (
            <>
              <fieldset>
                <legend className="mb-2 font-mono text-[9px] font-semibold uppercase tracking-wider text-muted">
                  Registration type
                </legend>
                <div className="grid grid-cols-2 gap-2 rounded-lg border border-white/[0.06] bg-deep p-1">
                  {[
                    { id: "citizen", label: "Citizen" },
                    { id: "authority", label: "Authority Member" },
                  ].map((option) => (
                    <button
                      aria-pressed={role === option.id}
                      className={`rounded px-3 py-2.5 font-mono text-[9px] font-semibold uppercase tracking-wide transition ${
                        role === option.id
                          ? "bg-cyan/10 text-cyan ring-1 ring-inset ring-cyan/30"
                          : "text-muted hover:text-ink"
                      }`}
                      key={option.id}
                      onClick={() => setRole(option.id)}
                      type="button"
                    >
                      {option.label}
                    </button>
                  ))}
                </div>
              </fieldset>

              <label className="block">
                <span className="mb-2 block font-mono text-[9px] font-semibold uppercase tracking-wider text-muted">
                  Full name
                </span>
                <input
                  autoComplete="name"
                  className="w-full rounded border border-white/10 bg-deep px-3.5 py-2.5 text-sm text-ink outline-none placeholder:text-muted/50 focus:border-cyan focus:ring-2 focus:ring-cyan/20"
                  maxLength={100}
                  onChange={(event) => setName(event.target.value)}
                  required
                  value={name}
                />
              </label>
            </>
          )}

          <label className="block">
            <span className="mb-2 block font-mono text-[9px] font-semibold uppercase tracking-wider text-muted">
              Email address
            </span>
            <input
              autoComplete="email"
              className="w-full rounded border border-white/10 bg-deep px-3.5 py-2.5 text-sm text-ink outline-none placeholder:text-muted/50 focus:border-cyan focus:ring-2 focus:ring-cyan/20"
              onChange={(event) => setEmail(event.target.value)}
              required
              type="email"
              value={email}
            />
          </label>

          <label className="block">
            <span className="mb-2 block font-mono text-[9px] font-semibold uppercase tracking-wider text-muted">
              Password
            </span>
            <input
              autoComplete={mode === "login" ? "current-password" : "new-password"}
              className="w-full rounded border border-white/10 bg-deep px-3.5 py-2.5 text-sm text-ink outline-none placeholder:text-muted/50 focus:border-cyan focus:ring-2 focus:ring-cyan/20"
              minLength={8}
              onChange={(event) => setPassword(event.target.value)}
              required
              type="password"
              value={password}
            />
            {mode === "register" && (
              <span className="mt-1 block font-mono text-[9px] text-muted/70">
                Use at least 8 characters.
              </span>
            )}
          </label>

          {mode === "register" && role === "authority" && (
            <label className="block">
              <span className="mb-2 block font-mono text-[9px] font-semibold uppercase tracking-wider text-muted">
                Authority verification code
                <span className="ml-1 font-normal normal-case tracking-normal">(optional for .gov email)</span>
              </span>
              <input
                autoComplete="off"
                className="w-full rounded border border-cyan/20 bg-deep px-3.5 py-2.5 font-mono text-sm text-ink outline-none placeholder:text-muted/50 focus:border-cyan focus:ring-2 focus:ring-cyan/20"
                onChange={(event) => setInviteCode(event.target.value)}
                placeholder="Enter official invite code"
                value={inviteCode}
              />
              <span className="mt-1 block font-mono text-[9px] text-muted/70">
                Authority registration requires an invite code or a .gov address.
              </span>
            </label>
          )}

          {error && (
            <p className="rounded border border-alert/20 bg-alert/10 px-3 py-2.5 text-sm text-alert" role="alert">
              {error}
            </p>
          )}

          <button
            className="w-full rounded bg-gradient-to-r from-cyan to-mint px-4 py-3 font-mono text-[10px] font-bold uppercase tracking-wider text-[#06202a] shadow-[0_0_18px_rgba(76,215,246,0.14)] transition hover:brightness-110 focus:outline-none focus:ring-2 focus:ring-cyan/40 disabled:cursor-wait disabled:opacity-60"
            disabled={isSubmitting}
            type="submit"
          >
            {isSubmitting ? "Please wait…" : mode === "login" ? "Sign in" : "Create account"}
          </button>
        </form>
      </section>
    </div>
  );
}

