import { getJwtSecret } from "../services/jwtSecret.js";

export async function verifyToken(request, response, next) {
  const authorization = request.get("authorization") ?? "";
  const [scheme, token] = authorization.split(/\s+/);

  if (scheme !== "Bearer" || !token) {
    response.status(401).json({ error: "A Bearer token is required." });
    return;
  }

  let secret;
  try {
    secret = await getJwtSecret();
  } catch (error) {
    next(error);
    return;
  }

  try {
    const claims = jwt.verify(token, secret, { issuer: "civicguard" });
    if (
      typeof claims !== "object" ||
      typeof claims.sub !== "string" ||
      typeof claims.email !== "string" ||
      !["citizen", "authority"].includes(claims.role)
    ) {
      response.status(401).json({ error: "The authentication token is invalid." });
      return;
    }

    request.user = {
      id: claims.sub,
      email: claims.email,
      role: claims.role,
    };
    next();
  } catch {
    response.status(401).json({ error: "The authentication token is invalid or expired." });
  }
}

export function requireAuthority(request, response, next) {
  if (request.user?.role !== "authority") {
    response.status(403).json({ error: "Authority access is required for this action." });
    return;
  }

  next();
}
"}

{"filePath":"c:\Users\codew\civicguard\civicguard\backend\routes\auth.js","content":"import { randomUUID } from "node:crypto";
import bcrypt from "bcryptjs";
import express from "express";
import jwt from "jsonwebtoken";
import { getUserByEmail, saveUser } from "../services/db.js";
import { getJwtSecret } from "../services/jwtSecret.js";

const router = express.Router();
const AUTHORITY_INVITE_CODE = "[REDACTED_AUTHORITY_INVITE_CODE]";
const PASSWORD_MIN_LENGTH = 8;

function normalizeRole(role) {
  const normalized = typeof role === "string" ? role.trim().toLowerCase() : "";
  if (normalized === "citizen") return "citizen";
  if (normalized === "authority" || normalized === "authority member") {
    return "authority";
  }
  return null;
}

function isValidEmail(email) {
  return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
}

function hasGovernmentDomain(email) {
  const domain = email.split("@")[1]?.toLowerCase() ?? "";
  return domain.endsWith(".gov");
}

function createAuthResponse(user, secret) {
  const token = jwt.sign(
    { email: user.email, role: user.role },
    secret,
    {
      subject: user.id,
      issuer: "civicguard",
      expiresIn: "8h",
    },
  );

  return {
    token,
    user: {
      id: user.id,
      name: user.name,
      email: user.email,
      role: user.role,
    },
  };
}

router.post("/register", async (request, response, next) => {
  try {
    const { name, email, password, inviteCode } = request.body ?? {};
    const role = normalizeRole(request.body?.role);

    if (
      typeof name !== "string" ||
      !name.trim() ||
      typeof email !== "string" ||
      !isValidEmail(email.trim()) ||
      typeof password !== "string" ||
      password.length < PASSWORD_MIN_LENGTH ||
      Buffer.byteLength(password, "utf8") > 72 ||
      !role
    ) {
      response.status(400).json({
        error: "Provide a name, valid email, password (8–72 bytes), and a valid role.",
      });
      return;
    }

    const normalizedEmail = email.trim().toLowerCase();
    if (
      role === "authority" &&
      inviteCode !== AUTHORITY_INVITE_CODE &&
      !hasGovernmentDomain(normalizedEmail)
    ) {
      response.status(403).json({
        error: "Authority registration requires the official invite code or a .gov email address.",
      });
      return;
    }

    const existingUser = await getUserByEmail(normalizedEmail);
    if (existingUser) {
      response.status(409).json({ error: "An account with this email already exists." });
      return;
    }

    const passwordHash = await bcrypt.hash(password, 12);
    const user = await saveUser({
      id: randomUUID(),
      name: name.trim(),
      email: normalizedEmail,
      passwordHash,
      role,
      createdAt: new Date().toISOString(),
    });

    response.status(201).json(createAuthResponse(user, await getJwtSecret()));
  } catch (error) {
    if (error.code === "DUPLICATE_EMAIL") {
      response.status(409).json({ error: "An account with this email already exists." });
      return;
    }
    next(error);
  }
});

router.post("/login", async (request, response, next) => {
  try {
    const { email, password } = request.body ?? {};
    if (typeof email !== "string" || typeof password !== "string") {
      response.status(400).json({ error: "Email and password are required." });
      return;
    }

    const user = await getUserByEmail(email.trim().toLowerCase());
    if (!user || !(await bcrypt.compare(password, user.passwordHash))) {
      response.status(401).json({ error: "Email or password is incorrect." });
      return;
    }

    response.json(createAuthResponse(user, await getJwtSecret()));
  } catch (error) {
    next(error);
  }
});

export default router;
"}

