@tailwind base;
@tailwind components;
@tailwind utilities;

:root {
  color: #dae2fd;
  background: #0b1326;
  font-family: "Geist", ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont,
    "Segoe UI", sans-serif;
  font-synthesis: none;
  text-rendering: optimizeLegibility;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

body {
  min-width: 320px;
  min-height: 100vh;
  margin: 0;
  background: #0b1326;
  overscroll-behavior: none;
}

body.has-cursor {
  cursor: none !important;
}

body.has-cursor input:not([type="button"]):not([type="submit"]):not([type="reset"]):not([type="checkbox"]):not([type="radio"]):not([type="range"]),
body.has-cursor textarea,
body.has-cursor [contenteditable="true"] {
  cursor: text !important;
}

.target-cursor-wrapper {
  position: fixed;
  top: 0;
  left: 0;
  width: 0;
  height: 0;
  z-index: 9999;
  pointer-events: none;
  mix-blend-mode: difference;
  transform: translate(-50%, -50%);
  transform-origin: center;
}

.target-cursor-dot {
  position: absolute;
  top: -2px;
  left: -2px;
  width: 4px;
  height: 4px;
  border-radius: 50%;
  background: #fff;
}

.target-cursor-bracket {
  position: absolute;
  width: 12px;
  height: 12px;
  border: 0 solid #fff;
}

.target-cursor-bracket-tl {
  border-top-width: 3px;
  border-left-width: 3px;
}

.target-cursor-bracket-tr {
  border-top-width: 3px;
  border-right-width: 3px;
}

.target-cursor-bracket-br {
  border-right-width: 3px;
  border-bottom-width: 3px;
}

.target-cursor-bracket-bl {
  border-bottom-width: 3px;
  border-left-width: 3px;
}

button,
input,
select,
textarea {
  font: inherit;
}

::selection {
  color: #0b1326;
  background: #4cd7f6;
}

::-webkit-scrollbar {
  width: 8px;
  height: 8px;
}

