      className="mx-auto flex w-full max-w-3xl flex-col gap-5 rounded-xl border border-cyan/20 bg-panel p-6 shadow-[0_0_28px_rgba(76,215,246,0.06)] sm:flex-row sm:items-center sm:p-8"
