      duration: 0.1,
      ease: "power3.out",
    });

    function startRotation() {
      rotationTween?.kill();
      gsap.set(wrapper, { rotation: 0 });
      rotationTween = gsap.to(wrapper, {
        rotation: 360,
        duration: 2,
        ease: "none",
        repeat: -1,
      });
    }

    function getTargetPositions(rect) {
      const left = rect.left - OUTSET - pointerX;
      const top = rect.top - OUTSET - pointerY;
      const right = rect.right + OUTSET - BRACKET_SIZE - pointerX;
      const bottom = rect.bottom + OUTSET - BRACKET_SIZE - pointerY;

      return {
        tl: { x: left, y: top },
        tr: { x: right, y: top },
        br: { x: right, y: bottom },
        bl: { x: left, y: bottom },
