}

.target-cursor-dot {
  position: absolute;
  top: -2px;
  left: -2px;
  width: 4px;
  height: 4px;
  border-radius: 50%;
  background: #fff;
}

.target-cursor-bracket {
  position: absolute;
  width: 12px;
  height: 12px;
  border: 0 solid #fff;
}

.target-cursor-bracket-tl {
  border-top-width: 3px;
  border-left-width: 3px;
}

.target-cursor-bracket-tr {
