import { createPortal } from "react-dom";
import { gsap } from "gsap";

const TARGET_SELECTOR = "a:not(.no-cursor-snap), button:not(.no-cursor-snap), .cursor-target";
const REST_POSITIONS = {
  tl: { x: -18, y: -18 },
  tr: { x: 6, y: -18 },
  br: { x: 6, y: 6 },
  bl: { x: -18, y: 6 },
};
const BRACKET_SIZE = 12;
const OUTSET = 3;
const EDGE_GUTTER = 30;

function clamp(value, min, max) {
  return Math.min(Math.max(value, min), Math.max(min, max));
}

function isTouchDevice() {
  return (
    "ontouchstart" in window ||
    navigator.maxTouchPoints > 0 ||
    window.matchMedia("(pointer: coarse)").matches
  );
}

function findTargetAtPoint(x, y) {
  const hit = document.elementFromPoint(x, y);
  return hit instanceof Element ? hit.closest(TARGET_SELECTOR) : null;
}

export default function TargetCursor() {
  const [enabled, setEnabled] = useState(false);
  const wrapperRef = useRef(null);
  const dotRef = useRef(null);
  const bracketRefs = useRef({});

  useEffect(() => {
    const smallScreen = window.matchMedia("(max-width: 768px)");
    const reducedMotion = window.matchMedia("(prefers-reduced-motion: reduce)");

    const updateAvailability = () => {
      setEnabled(!isTouchDevice() && !smallScreen.matches && !reducedMotion.matches);
    };

    updateAvailability();
    smallScreen.addEventListener("change", updateAvailability);
    reducedMotion.addEventListener("change", updateAvailability);
    window.addEventListener("resize", updateAvailability, { passive: true });

    return () => {
      smallScreen.removeEventListener("change", updateAvailability);
      reducedMotion.removeEventListener("change", updateAvailability);
      window.removeEventListener("resize", updateAvailability);
    };
  }, []);

  useEffect(() => {
    if (!enabled) return undefined;

    const wrapper = wrapperRef.current;
    const dot = dotRef.current;
    if (!wrapper || !dot) return undefined;

    const brackets = bracketRefs.current;
    let pointerX = window.innerWidth / 2;
    let pointerY = window.innerHeight / 2;
    let rawPointerX = pointerX;
    let rawPointerY = pointerY;
    let lockedTarget = null;
    let rotationTween = null;
    let restartTween = null;
    let pointerInside = false;
    const lockState = { strength: 0 };

    document.body.classList.add("has-cursor");
    gsap.set(wrapper, { x: pointerX, y: pointerY, rotation: 0, scale: 1, autoAlpha: 0 });
    Object.entries(REST_POSITIONS).forEach(([key, position]) => {
      gsap.set(brackets[key], position);
    });

    let moveX;
    let moveY;

    function createPointerTweens() {
      moveX = gsap.quickTo(wrapper, "x", {
        duration: 0.1,
        ease: "power3.out",
      });
      moveY = gsap.quickTo(wrapper, "y", {
        duration: 0.1,
        ease: "power3.out",
      });
    }

    createPointerTweens();

    function startRotation() {
      restartTween = null;
      rotationTween?.kill();
      gsap.set(wrapper, { rotation: 0 });
      rotationTween = gsap.to(wrapper, {
        rotation: 360,
        duration: 2,
        ease: "none",
        repeat: -1,
      });
    }

    function getTargetPositions(rect) {
      const left = rect.left - OUTSET;
      const top = rect.top - OUTSET;
      const right = rect.right + OUTSET - BRACKET_SIZE;
      const bottom = rect.bottom + OUTSET - BRACKET_SIZE;

      return {
        tl: { x: left, y: top },
        tr: { x: right, y: top },
        br: { x: right, y: bottom },
        bl: { x: left, y: bottom },
      };
    }

    function updateLockedBrackets() {
      if (!lockedTarget) return;
      if (!lockedTarget.isConnected) {
        releaseTarget();
        return;
      }

      const rect = lockedTarget.getBoundingClientRect();
      const positions = getTargetPositions(rect);
      const parallaxX = (rawPointerX - (rect.left + rect.width / 2)) * 0.2;
      const parallaxY = (rawPointerY - (rect.top + rect.height / 2)) * 0.2;
      const strength = lockState.strength;
      const maxBracketX = Math.max(0, window.innerWidth - BRACKET_SIZE);
      const maxBracketY = Math.max(0, window.innerHeight - BRACKET_SIZE);

      Object.entries(positions).forEach(([key, position]) => {
        const rest = REST_POSITIONS[key];
        gsap.set(brackets[key], {
          x: gsap.utils.interpolate(
            rest.x,
            clamp(position.x + parallaxX, 0, maxBracketX) - pointerX,
            strength,
          ),
          y: gsap.utils.interpolate(
            rest.y,
            clamp(position.y + parallaxY, 0, maxBracketY) - pointerY,
            strength,
          ),
        });
      });
    }

    function lockToTarget(target) {
      if (!target || target === lockedTarget) return;

      restartTween?.kill();
      restartTween = null;
      rotationTween?.kill();
      rotationTween = null;
      gsap.set(wrapper, { rotation: 0 });
      gsap.killTweensOf(lockState);
      lockState.strength = 0;
      lockedTarget = target;
      gsap.to(lockState, {
        strength: 1,
        duration: 0.2,
        ease: "power2.out",
      });
    }

    function releaseTarget() {
      if (!lockedTarget) return;

      lockedTarget = null;
      gsap.killTweensOf(lockState);
      lockState.strength = 0;
      Object.entries(REST_POSITIONS).forEach(([key, position]) => {
        gsap.to(brackets[key], {
          ...position,
          duration: 0.3,
          ease: "power3.out",
          overwrite: true,
        });
      });

      restartTween?.kill();
      restartTween = gsap.delayedCall(0.35, startRotation);
    }

    function updatePointer(clientX, clientY) {
      const reentering = !pointerInside;
      pointerInside = true;
      document.body.classList.add("has-cursor");
      rawPointerX = clientX;
      rawPointerY = clientY;
      pointerX = clamp(clientX, EDGE_GUTTER, window.innerWidth - EDGE_GUTTER);
      pointerY = clamp(clientY, EDGE_GUTTER, window.innerHeight - EDGE_GUTTER);

      if (reentering) {
        gsap.set(wrapper, {
          x: pointerX,
          y: pointerY,
          rotation: 0,
          scale: 1,
          autoAlpha: 1,
        });
      } else {
        gsap.set(wrapper, { autoAlpha: 1 });
        moveX(pointerX);
        moveY(pointerY);
      }

      const target = findTargetAtPoint(rawPointerX, rawPointerY);
      if (target) {
        lockToTarget(target);
      } else {
        releaseTarget();
        if (!rotationTween && !restartTween) startRotation();
      }
    }

    function handlePointerMove(event) {
      if (event.pointerType === "touch") return;
      updatePointer(event.clientX, event.clientY);
    }

    function handlePointerOver(event) {
      if (event.pointerType === "touch") return;
      updatePointer(event.clientX, event.clientY);
    }

    function handlePointerDown(event) {
      if (event.pointerType === "touch") return;
      gsap.to(dot, { scale: 0.7, duration: 0.3, overwrite: true });
      gsap.to(wrapper, { scale: 0.9, duration: 0.2, overwrite: true });
    }

    function handlePointerUp() {
      gsap.to(dot, { scale: 1, duration: 0.3, overwrite: true });
      gsap.to(wrapper, { scale: 1, duration: 0.2, overwrite: true });
    }

    function handleScroll() {
      if (!lockedTarget) return;
      if (findTargetAtPoint(rawPointerX, rawPointerY) !== lockedTarget) releaseTarget();
    }

    function handleWindowLeave() {
      if (!pointerInside) return;

      pointerInside = false;
      document.body.classList.remove("has-cursor");
      rotationTween?.kill();
      rotationTween = null;
      restartTween?.kill();
      restartTween = null;
      gsap.killTweensOf([wrapper, dot, ...Object.values(brackets), lockState]);
      lockState.strength = 0;
      lockedTarget = null;
      gsap.set(wrapper, { autoAlpha: 0, rotation: 0, scale: 1 });
      gsap.set(dot, { scale: 1 });
      Object.entries(REST_POSITIONS).forEach(([key, position]) => {
        gsap.set(brackets[key], position);
      });
      moveX.tween.kill();
      moveY.tween.kill();
      createPointerTweens();
    }

    function handlePointerOut(event) {
      if (event.relatedTarget === null) handleWindowLeave();
    }

    function handleVisibilityChange() {
      if (document.visibilityState === "hidden") handleWindowLeave();
    }

    gsap.ticker.add(updateLockedBrackets);
    window.addEventListener("pointermove", handlePointerMove, { passive: true });
    window.addEventListener("pointerover", handlePointerOver, { passive: true });
    window.addEventListener("pointerdown", handlePointerDown, { passive: true });
    window.addEventListener("pointerup", handlePointerUp, { passive: true });
    window.addEventListener("pointercancel", handlePointerUp, { passive: true });
    window.addEventListener("pointerleave", handleWindowLeave);
    window.addEventListener("blur", handleWindowLeave);
    document.addEventListener("pointerout", handlePointerOut);
    document.addEventListener("visibilitychange", handleVisibilityChange);
    window.addEventListener("scroll", handleScroll, { passive: true, capture: true });

    return () => {
      document.body.classList.remove("has-cursor");
      window.removeEventListener("pointermove", handlePointerMove);
      window.removeEventListener("pointerover", handlePointerOver);
      window.removeEventListener("pointerdown", handlePointerDown);
      window.removeEventListener("pointerup", handlePointerUp);
      window.removeEventListener("pointercancel", handlePointerUp);
      window.removeEventListener("pointerleave", handleWindowLeave);
      window.removeEventListener("blur", handleWindowLeave);
      document.removeEventListener("pointerout", handlePointerOut);
      document.removeEventListener("visibilitychange", handleVisibilityChange);
      window.removeEventListener("scroll", handleScroll, true);
      gsap.ticker.remove(updateLockedBrackets);
      rotationTween?.kill();
      restartTween?.kill();
      moveX.tween.kill();
      moveY.tween.kill();
      gsap.killTweensOf([wrapper, dot, ...Object.values(brackets), lockState]);
    };
  }, [enabled]);

  if (!enabled) return null;

  return createPortal(
    <div aria-hidden="true" className="target-cursor-wrapper" ref={wrapperRef}>
      <span className="target-cursor-dot" ref={dotRef} />
      <span className="target-cursor-bracket target-cursor-bracket-tl" ref={(node) => { bracketRefs.current.tl = node; }} />
      <span className="target-cursor-bracket target-cursor-bracket-tr" ref={(node) => { bracketRefs.current.tr = node; }} />
      <span className="target-cursor-bracket target-cursor-bracket-br" ref={(node) => { bracketRefs.current.br = node; }} />
      <span className="target-cursor-bracket target-cursor-bracket-bl" ref={(node) => { bracketRefs.current.bl = node; }} />
    </div>,
    document.body,
  );
}

import { useEffect, useMemo, useState } from "react";

const API_URL = "http://localhost:5000/api/reports";

const urgencyStyles = {
  low: "border-mint/25 bg-mint/10 text-mint",
  medium: "border-yellow-400/25 bg-yellow-400/10 text-yellow-300",
  high: "border-amber-400/25 bg-amber-400/10 text-amber-300",
  critical: "border-alert/30 bg-alert/10 text-alert",
};

const categoryStyles = {
  pothole: "text-alert",
  streetlight: "text-cyan",
  accessibility: "text-mint",
  garbage: "text-yellow-300",
};

const categories = ["All", "Pothole", "Streetlight", "Accessibility", "Garbage"];

function getSeverity(value) {
  if (typeof value === "string") {
    const normalized = value.trim().toLowerCase();
    const severityByLabel = {
      low: 1,
      minor: 1,
      medium: 3,
      moderate: 3,
      high: 4,
      severe: 4,
      critical: 5,
    };

    if (normalized in severityByLabel) return severityByLabel[normalized];
  }

  const score = Number(value);
  return Number.isFinite(score) && score >= 1 && score <= 5
    ? Math.round(score)
    : null;
}

function getUrgency(value, severity) {
  const normalized = typeof value === "string" ? value.trim().toLowerCase() : "";
  if (["low", "medium", "high", "critical"].includes(normalized)) {
    return normalized;
  }

  if (severity === null) return "medium";
  if (severity >= 5) return "critical";
  if (severity >= 4) return "high";
  if (severity >= 3) return "medium";
  return "low";
}

function getReportDetails(report) {
  const analysis =
    report.analysis && typeof report.analysis === "object" ? report.analysis : {};
  const category = String(report.category ?? analysis.category ?? "Uncategorized");
  const description = String(
    report.description ?? analysis.summary ?? analysis.description ?? "No description provided.",
  );
  const severity = getSeverity(
    analysis.severityScore ??
      analysis.severity_score ??
      analysis.severity ??
      report.severityScore ??
      report.severity,
  );
  const urgency = getUrgency(
    analysis.urgencyLevel ?? analysis.urgency ?? report.urgencyLevel ?? report.urgency,
    severity,
  );
  const timestamp = report.timestamp ?? report.createdAt ?? report.created_at;
  const date = timestamp ? new Date(timestamp) : null;

  return {
    id: report.id,
    title: String(
      report.title ?? analysis.title ?? analysis.issueTitle ?? `${category} report`,
    ),
    category,
    description,
    severity,
    urgency,
      tags: Array.isArray(analysis.tags) ? analysis.tags.filter((tag) => typeof tag === "string") : [],
      hasImage: Boolean(report.image),
    timestamp:
      date && !Number.isNaN(date.getTime())
        ? new Intl.DateTimeFormat(undefined, {
            dateStyle: "medium",
            timeStyle: "short",
          }).format(date)
        : "Time unavailable",
  };
}

function SeverityIndicator({ score }) {
  const activeColor = score >= 5 ? "bg-alert" : score >= 3 ? "bg-cyan" : "bg-mint";

  return (
    <div aria-label={score ? `Severity ${score} out of 5` : "Severity not rated"} role="img">
      <div aria-hidden="true" className="mt-2 grid h-1.5 grid-cols-5 gap-1">
        {[1, 2, 3, 4, 5].map((level) => (
          <span
            className={`rounded-full ${
              score !== null && level <= score ? `${activeColor} shadow-[0_0_7px_currentColor]` : "bg-white/10"
            }`}
            key={level}
          />
        ))}
      </div>
      <p className="mt-1.5 font-mono text-[10px] text-muted">
        {score === null ? "Not rated" : `${score} / 5`}
      </p>
    </div>
  );
}

function EmptyIncidentCard({ index }) {
  return (
    <article className="flex min-h-[340px] flex-col overflow-hidden rounded-xl border border-white/[0.06] bg-panel shadow-xl">
      <div className="border-b border-white/[0.04] bg-gradient-to-b from-cyan/[0.05] to-transparent px-5 pb-4 pt-5">
        <div className="flex items-center justify-between gap-3">
          <span className="font-mono text-[9px] font-semibold tracking-wide text-muted">
            INTAKE SLOT 0{index + 1}
          </span>
          <span className="rounded-full border border-white/10 bg-panel-raised px-2.5 py-1 font-mono text-[9px] uppercase tracking-wide text-muted">
            Awaiting data
          </span>
        </div>
        <h2 className="mt-3 font-display text-lg font-semibold text-ink">
          No incident submitted
        </h2>
        <p className="mt-2 font-mono text-[10px] text-muted/70">
          A new report will appear here
        </p>
      </div>

      <div className="flex flex-1 flex-col gap-4 px-5 py-4">
        <div className="rounded-lg bg-deep/75 p-3">
          <div className="flex items-center justify-between font-mono text-[9px]">
            <span className="text-muted">ISSUE SEVERITY</span>
            <span className="text-muted/70">NOT RATED</span>
          </div>
          <div aria-hidden="true" className="mt-2 grid h-1.5 grid-cols-5 gap-1">
            {Array.from({ length: 5 }, (_, segment) => (
              <span className="rounded-full bg-white/10" key={segment} />
            ))}
          </div>
          <p className="mt-1.5 font-mono text-[10px] text-muted/70">Awaiting analysis</p>
        </div>

        <div className="grid flex-1 place-items-center rounded-lg border border-white/[0.04] bg-deep/50">
          <div className="text-center">
            <span aria-hidden="true" className="font-mono text-2xl text-cyan/40">⌖</span>
            <p className="mt-2 font-mono text-[9px] uppercase tracking-wider text-muted/70">
              Incident details will populate on submission
            </p>
          </div>
        </div>

        <div className="mt-auto flex items-center justify-between border-t border-white/[0.06] pt-3 font-mono text-[9px] text-muted/70">
          <span>REPORT QUEUE</span>
          <span>NO DATA</span>
        </div>
      </div>
    </article>
  );
}

export default function ReportFeed() {
  const [reports, setReports] = useState([]);
  const [search, setSearch] = useState("");
  const [categoryFilter, setCategoryFilter] = useState("All");
  const [urgencyFilter, setUrgencyFilter] = useState("All urgencies");
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");

  useEffect(() => {
    const controller = new AbortController();

    async function loadReports() {
      try {
        const response = await fetch(API_URL, { signal: controller.signal });
        if (!response.ok) {
          throw new Error(`Could not load reports (${response.status}).`);
        }

        const data = await response.json();
        if (!Array.isArray(data)) {
          throw new Error("The reports response was not a list.");
        }

        setReports(data);
      } catch (fetchError) {
        if (fetchError.name !== "AbortError") {
          setError(fetchError.message || "Could not load reports.");
        }
      } finally {
        if (!controller.signal.aborted) setLoading(false);
      }
    }

    loadReports();
    return () => controller.abort();
  }, []);

  const reportDetails = useMemo(
    () => reports.map(getReportDetails),
    [reports],
  );
  const filteredReports = useMemo(() => {
    const query = search.trim().toLowerCase();
    return reportDetails.filter((report) => {
      const matchesQuery = !query ||
        [report.id, report.category, report.title, report.description, report.urgency]
          .join(" ")
          .toLowerCase()
          .includes(query);
      const matchesCategory =
        categoryFilter === "All" ||
        report.category.toLowerCase() === categoryFilter.toLowerCase();
      const matchesUrgency =
        urgencyFilter === "All urgencies" ||
        report.urgency.toLowerCase() === urgencyFilter.toLowerCase();

      return matchesQuery && matchesCategory && matchesUrgency;
    });
  }, [reportDetails, search, categoryFilter, urgencyFilter]);

  return (
    <section className="mx-auto w-full max-w-[1720px]">
      <div className="-mx-4 mb-5 border-y border-white/[0.06] bg-panel px-4 py-4 sm:-mx-6 sm:px-6 lg:-mx-8 lg:px-8">
        <div className="mx-auto flex max-w-[1720px] flex-col justify-between gap-4 lg:flex-row lg:items-center">
          <div className="flex flex-wrap items-center gap-x-6 gap-y-3">
            <div className="flex items-center gap-2.5">
              <span className="relative grid h-3 w-3 place-items-center rounded-full bg-alert/30">
                <span className="absolute h-3 w-3 animate-ping rounded-full bg-alert/50" />
                <span className="relative h-1.5 w-1.5 rounded-full bg-alert" />
              </span>
              <h1 className="font-display text-xl font-semibold tracking-tight text-ink">
                Live Incident Stream
              </h1>
            </div>
            <div className="flex items-center gap-2 rounded-full bg-panel-hover px-3 py-1.5 font-mono text-[10px] uppercase tracking-wider text-muted">
              Active load
              <span className="rounded bg-deep px-2 py-0.5 font-semibold text-cyan">
                {reports.length} reports
              </span>
            </div>
            <p className="hidden items-center gap-2 font-mono text-[10px] text-muted md:flex">
              <span className="text-mint">◆</span> Civic reporting network
            </p>
          </div>
          <div className="inline-flex w-fit items-center gap-2 rounded-full bg-panel-raised px-3 py-2 font-mono text-[10px] text-ink">
            <span className={`h-2 w-2 rounded-full ${loading ? "animate-pulse bg-cyan" : error ? "bg-alert" : "bg-mint shadow-[0_0_8px_#4edea3]"}`} />
            {loading ? "Connecting to report API" : error ? "API connection issue" : "Reports API connected"}
          </div>
        </div>
      </div>

      <div className="mb-6 space-y-4">
        <div className="flex flex-col gap-3 lg:flex-row lg:items-center lg:justify-between">
          <label className="relative block w-full lg:max-w-md">
            <span className="sr-only">Search by keyword, incident ID, or category</span>
            <span aria-hidden="true" className="pointer-events-none absolute inset-y-0 left-3.5 flex items-center text-muted">⌕</span>
            <input
              className="w-full rounded-xl border border-white/[0.06] bg-deep py-2.5 pl-10 pr-4 text-sm text-ink shadow-inner outline-none placeholder:text-muted/60 focus:border-cyan/60 focus:ring-2 focus:ring-cyan/10"
              onChange={(event) => setSearch(event.target.value)}
              placeholder="Search by keyword, incident ID, or category..."
              type="search"
              value={search}
            />
          </label>
          <div className="flex flex-wrap gap-2">
            <label className="flex items-center gap-2 rounded-xl bg-panel px-3 py-2 text-xs text-muted">
              <span className="text-cyan">!</span>
              <span>Urgency:</span>
              <select
                className="cursor-pointer bg-transparent font-mono text-[10px] font-semibold text-cyan outline-none"
                onChange={(event) => setUrgencyFilter(event.target.value)}
                value={urgencyFilter}
              >
                {["All urgencies", "Critical", "High", "Medium", "Low"].map((urgency) => (
                  <option className="bg-panel text-ink" key={urgency} value={urgency}>
                    {urgency}
                  </option>
                ))}
              </select>
            </label>
            <div className="flex items-center gap-2 rounded-xl bg-panel px-3 py-2 font-mono text-[10px] text-muted">
              <span className="text-mint">◉</span> All districts
            </div>
          </div>
        </div>

        <div aria-label="Filter reports by category" className="flex gap-2 overflow-x-auto pb-1">
          {categories.map((category) => {
            const count =
              category === "All"
                ? reports.length
                : reportDetails.filter(
                    (report) => report.category.toLowerCase() === category.toLowerCase(),
                  ).length;
            const isSelected = categoryFilter === category;

            return (
              <button
                aria-pressed={isSelected}
                className={`inline-flex shrink-0 items-center gap-2 rounded-full px-4 py-1.5 font-mono text-[10px] transition ${
                  isSelected
                    ? "bg-cyan font-semibold text-[#06202a] shadow-[0_0_12px_rgba(6,182,212,0.25)]"
                    : "bg-panel text-muted hover:bg-panel-hover hover:text-ink"
                }`}
                key={category}
                onClick={() => setCategoryFilter(category)}
                type="button"
              >
                {category}
                <span className={`rounded-full px-1.5 py-0.5 text-[9px] ${isSelected ? "bg-deep/15" : "bg-panel-hover text-ink"}`}>
                  {count}
                </span>
              </button>
            );
          })}
        </div>
      </div>

      {loading ? (
        <p aria-live="polite" className="rounded-xl border border-white/[0.06] bg-panel p-6 text-muted">
          Loading incident stream…
        </p>
      ) : error ? (
        <p
          aria-live="polite"
          className="rounded-xl border border-alert/20 bg-alert/10 p-6 text-sm text-alert"
          role="alert"
        >
          {error} Confirm the CivicGuard API is running and try again.
        </p>
      ) : (
        <div className={`grid grid-cols-1 gap-6 md:grid-cols-2 ${filteredReports.length === 4 ? "lg:grid-cols-2" : "lg:grid-cols-3"}`}>
          {filteredReports.map((report, index) => {
            const categoryStyle =
              categoryStyles[report.category.toLowerCase()] ??
              "text-cyan";
            const urgencyStyle = urgencyStyles[report.urgency] ?? urgencyStyles.medium;

            return (
              <article
                className={`group flex h-full flex-col overflow-hidden rounded-xl border bg-panel shadow-xl transition duration-300 hover:bg-panel-hover ${
                  report.urgency === "critical"
                    ? "border-alert/20"
                    : "border-white/[0.06]"
                }`}
                key={report.id ?? `${report.title}-${report.timestamp}-${index}`}
              >
