import nodemailer from "nodemailer";

let transporter;

function getTransporter() {
  const { SMTP_HOST, SMTP_PORT, SMTP_USER, SMTP_PASSWORD } = process.env;
  const suppliedSettings = [SMTP_HOST, SMTP_PORT, SMTP_USER, SMTP_PASSWORD].filter(Boolean).length;

  if (suppliedSettings === 0) return null;
  if (suppliedSettings !== 4) {
    throw new Error("Configure SMTP_HOST, SMTP_PORT, SMTP_USER, and SMTP_PASSWORD together.");
  }

  if (!transporter) {
    transporter = nodemailer.createTransport({
      host: SMTP_HOST,
      port: Number(SMTP_PORT),
      secure: String(process.env.SMTP_SECURE).toLowerCase() === "true",
      auth: { user: SMTP_USER, pass: SMTP_PASSWORD },
    });
  }

  return transporter;
}

export async function sendVerificationEmail({ email, name, verificationUrl }) {
  const mailer = getTransporter();
  if (!mailer) {
    if (process.env.NODE_ENV === "production") {
      throw new Error("Email verification delivery is not configured. Set the SMTP environment variables.");
    }
    return { delivered: false };
  }

  await mailer.sendMail({
    from: process.env.SMTP_FROM || process.env.SMTP_USER,
    to: email,
    subject: "Verify your CivicGuard email",
    text: `Hello ${name},\n\nVerify your email address to activate your CivicGuard account:\n${verificationUrl}\n\nThis link expires in 24 hours. If you did not create this account, ignore this email.`,
    html: `<p>Hello ${escapeHtml(name)},</p><p>Verify your email address to activate your CivicGuard account:</p><p><a href="${escapeHtml(verificationUrl)}">Verify email</a></p><p>This link expires in 24 hours. If you did not create this account, ignore this email.</p>`,
  });

  return { delivered: true };
}

function escapeHtml(value) {
  return String(value).replace(/[&<>"']/g, (character) => ({
    "&": "&amp;",
    "<": "&lt;",
    ">": "&gt;",
    '"': "&quot;",
    "'": "&#39;",
  })[character]);
}

import { randomUUID } from "node:crypto";
import { DeleteObjectCommand, PutObjectCommand, S3Client } from "@aws-sdk/client-s3";
import { mkdir, unlink, writeFile } from "node:fs/promises";
import path from "node:path";
import { fileURLToPath } from "node:url";
import dotenv from "dotenv";

dotenv.config({ path: fileURLToPath(new URL("../.env", import.meta.url)) });

const backendDirectory = fileURLToPath(new URL("..", import.meta.url));
const uploadsDirectory = path.resolve(process.env.UPLOAD_DIR ?? path.join(backendDirectory, "uploads"));
const storageMode = process.env.REPORT_IMAGE_STORAGE ?? "local";
const bucket = process.env.S3_BUCKET;
const region = process.env.S3_REGION;
const publicBaseUrl = process.env.S3_PUBLIC_BASE_URL?.replace(/\/$/, "");
const endpoint = process.env.S3_ENDPOINT || undefined;

if (!["local", "s3"].includes(storageMode)) {
  throw new Error("REPORT_IMAGE_STORAGE must be either 'local' or 's3'.");
}
if (storageMode === "s3" && (!bucket || !region || !publicBaseUrl)) {
  throw new Error("S3 image storage requires S3_BUCKET, S3_REGION, and S3_PUBLIC_BASE_URL.");
}

const s3 = storageMode === "s3"
  ? new S3Client({
      region,
      endpoint,
      forcePathStyle: Boolean(endpoint),
    })
  : null;

const extensionByMimeType = {
  "image/avif": "avif",
  "image/gif": "gif",
  "image/heic": "heic",
  "image/heif": "heif",
  "image/jpeg": "jpg",
  "image/png": "png",
  "image/webp": "webp",
};

function objectUrl(key) {
  return `${publicBaseUrl}/${key.split("/").map(encodeURIComponent).join("/")}`;
}

export function getImageStorageMode() {
  return storageMode;
}

export function getUploadsDirectory() {
  return uploadsDirectory;
}

export async function ensureImageStorageReady() {
  if (storageMode === "local") await mkdir(uploadsDirectory, { recursive: true });
}

export async function storeReportImage({ reportId, file }) {
  if (!file) return null;

  const extension = extensionByMimeType[file.mimetype];
  if (!extension) throw new TypeError("Unsupported image type for storage.");
  const objectKey = `incidents/${reportId}/${randomUUID()}.${extension}`;

  if (storageMode === "s3") {
    await s3.send(new PutObjectCommand({
      Bucket: bucket,
      Key: objectKey,
      Body: file.buffer,
      ContentType: file.mimetype,
      CacheControl: "public, max-age=31536000, immutable",
    }));
    return {
      url: objectUrl(objectKey),
      objectKey,
      originalName: path.basename(file.originalname || `evidence.${extension}`),
      mimeType: file.mimetype,
      size: file.size,
      storage: "s3",
    };
  }

  await ensureImageStorageReady();
  const fileName = path.basename(objectKey);
  await writeFile(path.join(uploadsDirectory, fileName), file.buffer, {
    flag: "wx",
    mode: 0o600,
  });
  const apiBaseUrl = (process.env.API_PUBLIC_BASE_URL || `http://localhost:${process.env.PORT || 5000}`).replace(/\/$/, "");

  return {
    url: `${apiBaseUrl}/uploads/${encodeURIComponent(fileName)}`,
    objectKey: fileName,
    originalName: path.basename(file.originalname || `evidence.${extension}`),
    mimeType: file.mimetype,
    size: file.size,
    storage: "local",
  };
}

export async function deleteStoredImage(image) {
  if (!image?.objectKey) return;

  if (image.storage === "s3") {
    await s3.send(new DeleteObjectCommand({ Bucket: bucket, Key: image.objectKey }));
    return;
  }

  await unlink(path.join(uploadsDirectory, path.basename(image.objectKey))).catch((error) => {
    if (error.code !== "ENOENT") throw error;
  });
}

import { createHash, randomBytes, randomUUID } from "node:crypto";
import bcrypt from "bcryptjs";
import express from "express";
import rateLimit from "express-rate-limit";
import jwt from "jsonwebtoken";
import {
  deleteUnverifiedUser,
  getUserByEmail,
  saveUser,
  setEmailVerification,
  updateEmailVerification,
  verifyUserEmail,
} from "../services/db.js";
import { getJwtSecret } from "../services/jwtSecret.js";
import { sendVerificationEmail } from "../services/mailer.js";

const router = express.Router();
const PASSWORD_MIN_LENGTH = 8;
const VERIFICATION_TTL_MS = 24 * 60 * 60 * 1000;
const authLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  limit: 10,
  standardHeaders: "draft-8",
  legacyHeaders: false,
  message: { error: "Too many authentication attempts. Please try again later." },
});

router.use(authLimiter);

function normalizeRole(role) {
  const normalized = typeof role === "string" ? role.trim().toLowerCase() : "";
  if (normalized === "citizen") return "citizen";
  if (normalized === "authority" || normalized === "authority member") {
    return "authority";
  }
  return null;
}

function isValidEmail(email) {
  return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
}

function hasGovernmentDomain(email) {
  const domain = email.split("@")[1]?.toLowerCase() ?? "";
  return domain.endsWith(".gov");
}

function createAuthResponse(user, secret) {
  const token = jwt.sign(
    { email: user.email, role: user.role },
    secret,
    {
      subject: user.id,
      issuer: "civicguard",
      expiresIn: "8h",
    },
  );

  return {
    token,
    user: {
      id: user.id,
      name: user.name,
      email: user.email,
      role: user.role,
    },
  };
}

function hashVerificationToken(token) {
  return createHash("sha256").update(token).digest("hex");
}

function verificationLink(token) {
  const frontendUrl = (process.env.FRONTEND_URL || "http://localhost:5173").replace(/\/$/, "");
  return `${frontendUrl}/?verifyEmail=${encodeURIComponent(token)}`;
}

async function issueVerification(user, existingTokenHash = null) {
  const rawToken = randomBytes(32).toString("base64url");
  const tokenHash = hashVerificationToken(rawToken);
  const expiresAt = Date.now() + VERIFICATION_TTL_MS;

  if (existingTokenHash) {
    const updated = await updateEmailVerification(user.id, tokenHash, expiresAt);
    if (!updated) return null;
  } else {
    await setEmailVerification(user.id, tokenHash, expiresAt);
  }

  const url = verificationLink(rawToken);
  const delivery = await sendVerificationEmail({
    email: user.email,
    name: user.name,
    verificationUrl: url,
  });

  return {
    verificationRequired: true,
    message: "Check your email for a verification link. The link expires in 24 hours.",
    ...(delivery.delivered ? {} : { verificationUrl: url }),
  };
}

router.post("/register", async (request, response, next) => {
  try {
    const { name, email, password, inviteCode } = request.body ?? {};
    const role = normalizeRole(request.body?.role);

    if (
      typeof name !== "string" ||
      !name.trim() ||
      typeof email !== "string" ||
      !isValidEmail(email.trim()) ||
      typeof password !== "string" ||
      password.length < PASSWORD_MIN_LENGTH ||
      Buffer.byteLength(password, "utf8") > 72 ||
      !role
    ) {
      response.status(400).json({
        error: "Provide a name, valid email, password (8–72 bytes), and a valid role.",
      });
      return;
    }

    const normalizedEmail = email.trim().toLowerCase();
    if (
      role === "authority" &&
      (!process.env.AUTHORITY_INVITE_CODE || inviteCode !== process.env.AUTHORITY_INVITE_CODE) &&
      !hasGovernmentDomain(normalizedEmail)
    ) {
      response.status(403).json({
        error: "Authority registration requires the official invite code or a .gov email address.",
      });
      return;
    }

    const existingUser = await getUserByEmail(normalizedEmail);
    if (existingUser) {
      if (!existingUser.emailVerified) {
        const verification = await issueVerification(existingUser, "refresh");
        response.status(202).json(verification ?? {
          verificationRequired: true,
          message: "If the account is eligible, a verification link will be sent.",
        });
        return;
      }
      response.status(409).json({ error: "An account with this email already exists." });
      return;
    }

    const passwordHash = await bcrypt.hash(password, 12);
    const user = await saveUser({
      id: randomUUID(),
      name: name.trim(),
      email: normalizedEmail,
      passwordHash,
      role,
      emailVerified: false,
      createdAt: new Date().toISOString(),
    });

    try {
      response.status(201).json(await issueVerification(user));
    } catch (error) {
      await deleteUnverifiedUser(user.id);
      throw error;
    }
  } catch (error) {
    if (error.code === "DUPLICATE_EMAIL") {
      response.status(409).json({ error: "An account with this email already exists." });
      return;
    }
    next(error);
  }
});

router.post("/verify-email", async (request, response, next) => {
  try {
    const token = request.body?.token;
    if (typeof token !== "string" || token.length < 32 || token.length > 256) {
      response.status(400).json({ error: "A valid email verification token is required." });
      return;
    }

    const user = await verifyUserEmail(hashVerificationToken(token));
    if (!user) {
      response.status(400).json({ error: "The verification link is invalid or expired." });
      return;
    }

    response.json(createAuthResponse(user, await getJwtSecret()));
  } catch (error) {
    next(error);
  }
});

router.post("/resend-verification", async (request, response, next) => {
  try {
    const email = request.body?.email;
    if (typeof email !== "string" || !isValidEmail(email.trim())) {
      response.status(400).json({ error: "A valid email address is required." });
      return;
    }

    const user = await getUserByEmail(email.trim().toLowerCase());
    if (!user || user.emailVerified) {
      response.json({ message: "If the account needs verification, a new link will be sent." });
      return;
    }

    const verification = await issueVerification(user, "refresh");
    response.json(verification ?? {
      message: "If the account needs verification, a new link will be sent.",
    });
  } catch (error) {
    next(error);
  }
});

router.post("/login", async (request, response, next) => {
  try {
    const { email, password } = request.body ?? {};
    if (typeof email !== "string" || typeof password !== "string") {
      response.status(400).json({ error: "Email and password are required." });
      return;
    }

    const user = await getUserByEmail(email.trim().toLowerCase());
    if (!user || !(await bcrypt.compare(password, user.passwordHash))) {
      response.status(401).json({ error: "Email or password is incorrect." });
      return;
    }
    if (!user.emailVerified) {
      response.status(403).json({ error: "Verify your email address before signing in." });
      return;
    }

    response.json(createAuthResponse(user, await getJwtSecret()));
  } catch (error) {
    next(error);
  }
});

