                  ) : null}

                  <div className="mt-auto flex items-center justify-between border-t border-white/[0.06] pt-3 font-mono text-[9px] text-muted">
                    <span>REPORT RECEIVED</span>
                    <span className="inline-flex items-center gap-1.5 text-mint">
                      <span className="h-1.5 w-1.5 rounded-full bg-mint" />
                      {report.urgency === "critical" ? "PRIORITY REVIEW" : "IN QUEUE"}
                    </span>
                  </div>
                </div>
              </article>
            );
          })}
        </div>
      )}

      {!loading && !error && filteredReports.length === 0 && (
        <div className="mb-5 flex flex-col gap-1 rounded-lg border border-white/[0.06] bg-panel/70 px-4 py-3 sm:flex-row sm:items-center sm:justify-between">
          <p className="text-sm font-medium text-ink">
            {search || categoryFilter !== "All" || urgencyFilter !== "All urgencies"
              ? "No reports match these filters"
              : "No reports have been submitted yet"}
          </p>
          <p className="font-mono text-[9px] text-muted">
            {search || categoryFilter !== "All" || urgencyFilter !== "All urgencies"
              ? "Adjust search or filters to view results"
              : "Incident cards will populate as reports arrive"}
          </p>
        </div>
      )}

      {!loading && filteredReports.length === 0 && (
        <div className="grid grid-cols-1 gap-6 md:grid-cols-2 lg:grid-cols-3">
          {[0, 1, 2].map((slot) => (
            <EmptyIncidentCard index={slot} key={slot} />
          ))}
        </div>
      )}

      {!loading && !error && filteredReports.length > 0 && (
        <div className="mt-6 flex flex-col gap-2 border-t border-white/[0.06] pt-4 font-mono text-[9px] uppercase tracking-wide text-muted sm:flex-row sm:items-center sm:justify-between">
          <span>Showing {filteredReports.length} of {reports.length} reports</span>
          <span className="inline-flex items-center gap-2 text-mint">
            <span className="h-1.5 w-1.5 rounded-full bg-mint" />
            {lastSynced ? `Updated ${lastSynced.toLocaleTimeString()}` : "Waiting for sync"}
          </span>
        </div>
      )}
    </section>
  );
}

const REPORTS_URL = "http://localhost:5000/api/reports";
const API_URL = "http://localhost:5000/api";

async function postAuthRequest(path, credentials) {
  const response = await fetch(`${API_URL}/auth/${path}`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(credentials),
  });

  const result = await response.json().catch(() => ({}));
  if (!response.ok) {
    throw new Error(result.error ?? `Authentication failed (${response.status}).`);
  }

  return result;
}

export async function loginUser(credentials) {
  try {
    return await postAuthRequest("login", credentials);
  } catch (error) {
    console.error("[CivicGuard API] Login failed:", error);
    throw error;
  }
}

export async function registerUser(details) {
  try {
    return await postAuthRequest("register", details);
  } catch (error) {
    console.error("[CivicGuard API] Registration failed:", error);
    throw error;
  }
}

export async function verifyEmailToken(token) {
  return postAuthRequest("verify-email", { token });
}

export async function resendVerificationEmail(email) {
  return postAuthRequest("resend-verification", { email });
}

export async function getReports() {
  try {
    const response = await fetch(REPORTS_URL);
    if (!response.ok) {
      const details = await response.json().catch(() => null);
      throw new Error(
        details?.error ?? `The reports request failed with status ${response.status}.`,
      );
    }

    return await response.json();
  } catch (error) {
    const message = error instanceof Error ? error.message : "Unknown network error.";
    console.error("[CivicGuard API] Failed to fetch reports:", error);
    throw new Error(`Unable to get reports: ${message}`, { cause: error });
  }
}

export async function createReport(formData) {
  try {
    const response = await fetch(REPORTS_URL, {
      method: "POST",
      body: formData,
    });
    if (!response.ok) {
      const details = await response.json().catch(() => null);
      throw new Error(
        details?.error ?? `The report request failed with status ${response.status}.`,
      );
    }

    return await response.json();
  } catch (error) {
    const message = error instanceof Error ? error.message : "Unknown network error.";
    console.error("[CivicGuard API] Failed to create report:", error);
    throw new Error(`Unable to create report: ${message}`, { cause: error });
  }
}

export async function updateReportStatus(id, status, token) {
  try {
    const response = await fetch(
      `${REPORTS_URL}/${encodeURIComponent(id)}/status`,
      {
        method: "PATCH",
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${token}`,
        },
        body: JSON.stringify({ status }),
      },
    );
    if (!response.ok) {
      const details = await response.json().catch(() => null);
      throw new Error(
        details?.error ?? `The status update failed with status ${response.status}.`,
      );
    }

    return await response.json();
  } catch (error) {
    const message = error instanceof Error ? error.message : "Unknown network error.";
    console.error("[CivicGuard API] Failed to update report status:", error);
    throw new Error(`Unable to update report status: ${message}`, { cause: error });
  }
}

export async function deleteReport(id, token) {
  try {
    const response = await fetch(`${REPORTS_URL}/${encodeURIComponent(id)}`, {
      method: "DELETE",
      headers: { Authorization: `Bearer ${token}` },
    });
    if (!response.ok) {
      const details = await response.json().catch(() => null);
      throw new Error(
        details?.error ?? `The report deletion failed with status ${response.status}.`,
      );
    }

    return await response.json();
  } catch (error) {
    const message = error instanceof Error ? error.message : "Unknown network error.";
    console.error("[CivicGuard API] Failed to delete report:", error);
    throw new Error(`Unable to delete report: ${message}`, { cause: error });
  }
}

import { useEffect, useMemo, useState } from "react";
import {
  deleteReport as deleteReportRequest,
  updateReportStatus as saveReportStatus,
} from "../services/api.js";
import { useAuth } from "../context/AuthContext.jsx";

const API_URL = "http://localhost:5000/api/reports";
const REFRESH_INTERVAL_MS = 5000;
const statuses = ["Pending", "In Progress", "Resolved"];
const urgencyOrder = { critical: 4, high: 3, medium: 2, low: 1 };

const urgencyStyles = {
  critical: "border-alert/30 bg-alert/10 text-alert",
  high: "border-amber-400/25 bg-amber-400/10 text-amber-300",
  medium: "border-yellow-400/25 bg-yellow-400/10 text-yellow-300",
  low: "border-mint/25 bg-mint/10 text-mint",
};

const statusStyles = {
  Pending: "bg-yellow-400/10 text-yellow-300",
  "In Progress": "bg-cyan/10 text-cyan",
  Resolved: "bg-mint/10 text-mint",
};

function normalizeReport(report, index) {
  const analysis =
    report.analysis && typeof report.analysis === "object" ? report.analysis : {};
  const severityValue =
    report.severityScore ??
    report.severity_score ??
    analysis.severityScore ??
    analysis.severity_score ??
    analysis.severity;
  const severityNumber = Number(severityValue);
  const severityScore =
    Number.isFinite(severityNumber) && severityNumber >= 1 && severityNumber <= 5
      ? Math.round(severityNumber)
      : null;
  const urgencyLevel = String(
    report.urgencyLevel ??
      report.urgency ??
      analysis.urgencyLevel ??
      analysis.urgency ??
      "Low",
  );
  const category = String(report.category ?? analysis.category ?? "Uncategorized");

  return {
    id: String(report.id ?? `report-${index}`),
    title: String(
      report.title ?? analysis.title ?? analysis.issueTitle ?? `${category} report`,
    ),
    category,
    description: String(
      report.description ??
        analysis.summary ??
        analysis.description ??
        "No description provided.",
    ),
    urgencyLevel,
    severityScore,
    timestamp: report.timestamp ?? report.createdAt ?? report.created_at,
    status: statuses.includes(report.status) ? report.status : "Pending",
  };
}

function formatTimestamp(timestamp) {
  if (!timestamp) return "—";
  const date = new Date(timestamp);
  if (Number.isNaN(date.getTime())) return "—";

  return new Intl.DateTimeFormat(undefined, {
    dateStyle: "medium",
    timeStyle: "short",
  }).format(date);
}

function SummaryCard({ label, value, detail, accent }) {
  return (
    <article className="rounded-xl border border-white/[0.06] bg-panel p-5 shadow-lg">
      <p className="font-mono text-[10px] uppercase tracking-wider text-muted">{label}</p>
      <p className={`mt-2 font-display text-3xl font-bold tracking-tight ${accent}`}>{value}</p>
      <p className="mt-1 text-xs text-muted">{detail}</p>
    </article>
  );
}

function csvCell(value) {
  let text = String(value ?? "");
  if (/^[\s]*[=+\-@]/.test(text)) text = `'${text}`;
  return `"${text.replaceAll('"', '""')}"`;
}

function exportReportsCsv(reports, statusById) {
  const columns = ["ID", "Category", "Severity", "Urgency", "Status", "Date"];
  const rows = reports.map((report) => [
    report.id,
    report.category,
    report.severityScore ?? "",
    report.urgencyLevel,
    statusById[report.id] ?? report.status,
    formatTimestamp(report.timestamp),
  ]);
  const csv = [columns, ...rows].map((row) => row.map(csvCell).join(",")).join("\r\n");
  const blob = new Blob([`\uFEFF${csv}`], { type: "text/csv;charset=utf-8" });
  const url = URL.createObjectURL(blob);
  const downloadLink = document.createElement("a");

  downloadLink.href = url;
  downloadLink.download = "civicguard_incidents.csv";
  document.body.append(downloadLink);
  downloadLink.click();
  downloadLink.remove();
  window.setTimeout(() => URL.revokeObjectURL(url), 1000);
}

export default function AdminDashboard({ onNotify }) {
  const { token } = useAuth();
  const [reports, setReports] = useState([]);
  const [statusById, setStatusById] = useState({});
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  const [statusError, setStatusError] = useState("");
  const [updatingReportId, setUpdatingReportId] = useState(null);
  const [deletingReportId, setDeletingReportId] = useState(null);
  const [lastSynced, setLastSynced] = useState(null);
  const [refreshKey, setRefreshKey] = useState(0);

  useEffect(() => {
    const controller = new AbortController();
    let requestInFlight = false;

    async function loadReports() {
      if (requestInFlight) return;
      requestInFlight = true;
      try {
        const response = await fetch(API_URL, { signal: controller.signal });
        if (!response.ok) {
          throw new Error(`Could not load reports (${response.status}).`);
        }

        const data = await response.json();
        if (!Array.isArray(data)) {
          throw new Error("The reports response was not a list.");
        }

        const normalizedReports = data.map(normalizeReport);
        setReports(normalizedReports);
        setLastSynced(new Date());
        setError("");
        setStatusById(
          Object.fromEntries(
            normalizedReports.map((report) => [report.id, report.status]),
          ),
        );
      } catch (loadError) {
        if (loadError.name !== "AbortError") {
          setError(loadError.message || "Could not load reports.");
        }
      } finally {
        requestInFlight = false;
        if (!controller.signal.aborted) setLoading(false);
      }
    }

    loadReports();
    const intervalId = window.setInterval(loadReports, REFRESH_INTERVAL_MS);
    return () => {
      window.clearInterval(intervalId);
      controller.abort();
    };
  }, [refreshKey]);

  const sortedReports = useMemo(
    () =>
      [...reports].sort((first, second) => {
        const firstUrgency =
          urgencyOrder[first.urgencyLevel.toLowerCase()] ?? 0;
        const secondUrgency =
          urgencyOrder[second.urgencyLevel.toLowerCase()] ?? 0;

        return (
          secondUrgency - firstUrgency ||
          (second.severityScore ?? 0) - (first.severityScore ?? 0)
        );
      }),
    [reports],
  );

  const criticalCount = reports.filter(
    (report) => report.urgencyLevel.toLowerCase() === "critical",
  ).length;
  const resolvedCount = reports.filter(
    (report) => statusById[report.id] === "Resolved",
  ).length;
  const resolutionRate = reports.length
    ? Math.round((resolvedCount / reports.length) * 100)
    : 0;

  async function updateStatus(reportId, status) {
    setUpdatingReportId(reportId);
    setStatusError("");

    try {
      const updatedReport = await saveReportStatus(reportId, status, token);
      setStatusById((currentStatuses) => ({
        ...currentStatuses,
        [reportId]: updatedReport.status,
      }));
      setReports((currentReports) =>
        currentReports.map((report) =>
          report.id === reportId ? { ...report, status: updatedReport.status } : report,
        ),
      );
      onNotify?.(`Status updated to ${updatedReport.status}.`);
    } catch (updateError) {
      setStatusError(updateError.message || "Could not update report status.");
    } finally {
      setUpdatingReportId(null);
    }
  }

  async function handleDeleteReport(report) {
    const confirmed = window.confirm(
      `Delete “${report.title}”? This action cannot be undone.`,
    );
    if (!confirmed) return;

    setDeletingReportId(report.id);
    setStatusError("");
    try {
      await deleteReportRequest(report.id, token);
      setReports((currentReports) => currentReports.filter((item) => item.id !== report.id));
      setStatusById((currentStatuses) => {
        const nextStatuses = { ...currentStatuses };
        delete nextStatuses[report.id];
        return nextStatuses;
      });
      onNotify?.("Incident deleted.");
    } catch (deleteError) {
      setStatusError(deleteError.message || "Could not delete the report.");
    } finally {
      setDeletingReportId(null);
    }
  }

  return (
    <section className="mx-auto w-full max-w-[1720px] space-y-7">
      <header className="flex flex-col gap-4 sm:flex-row sm:items-end sm:justify-between">
        <div>
          <p className="font-mono text-[10px] font-semibold uppercase tracking-[0.16em] text-cyan">
            CivicGuard staff / operations
          </p>
