                          type="button"
                        >
                          {isDeleting ? "Deleting…" : "Delete"}
                        </button>
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
        )}
      </section>
    </section>
  );
}

import { randomUUID } from "node:crypto";
import cors from "cors";
import dotenv from "dotenv";
import express from "express";
import multer from "multer";
import { requireAuthority, verifyToken } from "./middleware/auth.js";
import authRoutes from "./routes/auth.js";
import {
  deleteReport,
  getReports,
  saveReport,
  updateReportStatus,
} from "./services/db.js";
import { analyzeIssueReport } from "./services/geminiService.js";
import { getJwtSecret } from "./services/jwtSecret.js";
import {
  deleteStoredImage,
  ensureImageStorageReady,
  getImageStorageMode,
  getUploadsDirectory,
  storeReportImage,
} from "./services/imageStorage.js";

dotenv.config();

const app = express();
const MAX_IMAGE_SIZE_BYTES = 10 * 1024 * 1024;
const trustProxyHops = Number.parseInt(process.env.TRUST_PROXY_HOPS ?? "0", 10);
if (Number.isInteger(trustProxyHops) && trustProxyHops > 0) {
  app.set("trust proxy", trustProxyHops);
}

const upload = multer({
  storage: multer.memoryStorage(),
  limits: {
    fileSize: MAX_IMAGE_SIZE_BYTES,
    files: 1,
  },
  fileFilter(_request, file, callback) {
    if (!file.mimetype.startsWith("image/")) {
      callback(new Error("Uploaded file must be an image."));
      return;
    }

    callback(null, true);
  },
});

app.use(cors());
app.use(express.json({ limit: "1mb" }));
if (getImageStorageMode() === "local") {
  app.use("/uploads", express.static(getUploadsDirectory(), { immutable: true, maxAge: "1y" }));
}
app.use("/api/auth", authRoutes);

app.post("/api/reports", upload.single("image"), async (request, response, next) => {
  let storedImage = null;
  try {
    const description = request.body?.description;
    if (typeof description !== "string" || description.trim().length === 0) {
      console.error("[POST /api/reports] Validation failed: description is required.");
      response.status(400).json({ error: "A non-empty description is required." });
      return;
    }

    const selectedCategory =
      typeof request.body?.category === "string" ? request.body.category.trim() : "";
    const customCategory =
      typeof request.body?.customCategory === "string"
        ? request.body.customCategory.trim()
        : "";

    if (selectedCategory === "Other" && customCategory.length < 2) {
      console.error("[POST /api/reports] Validation failed: custom category is required for Other.");
      response.status(400).json({ error: "Enter a custom category when selecting Other." });
      return;
    }

    const normalizedDescription = description.trim();
    const analysis = await analyzeIssueReport(
      normalizedDescription,
      request.file ?? null,
    );

    if (analysis == null) {
      throw new Error("Issue analysis returned no result.");
    }

    const reportId = randomUUID();
    storedImage = request.file
      ? await storeReportImage({ reportId, file: request.file })
      : null;

    const report = {
      id: reportId,
      timestamp: new Date().toISOString(),
      title:
        typeof request.body?.title === "string" && request.body.title.trim()
          ? request.body.title.trim()
          : analysis.summary,
      category:
        selectedCategory === "Other"
          ? customCategory
          : selectedCategory || analysis.category,
      description: normalizedDescription,
      analysis,
      district:
        typeof request.body?.district === "string" && request.body.district.trim()
          ? request.body.district.trim()
          : "Unassigned",
      image: storedImage,
    };

    await saveReport(report);
    response.status(201).json(report);
  } catch (error) {
    if (storedImage) {
      await deleteStoredImage(storedImage).catch((cleanupError) => {
        console.error("[POST /api/reports] Could not remove unreferenced image:", cleanupError);
      });
    }
    console.error("[POST /api/reports] Failed to analyze or save report:", error);
    next(error);
  }
});

app.get("/api/reports", async (_request, response, next) => {
  try {
    response.json(await getReports());
  } catch (error) {
    next(error);
  }
});

app.patch(
  "/api/reports/:id/status",
  verifyToken,
  requireAuthority,
  async (request, response, next) => {
  try {
    const { status } = request.body ?? {};
    if (!status || !["Pending", "In Progress", "Resolved"].includes(status)) {
      response.status(400).json({
        error: "Status must be Pending, In Progress, or Resolved.",
      });
      return;
    }

    const report = await updateReportStatus(request.params.id, status);
    if (!report) {
      response.status(404).json({ error: "Report not found." });
      return;
    }

    response.json(report);
  } catch (error) {
    next(error);
  }
  },
);

app.delete(
  "/api/reports/:id",
  verifyToken,
  requireAuthority,
  async (request, response, next) => {
    try {
      const report = await deleteReport(request.params.id);
      if (!report) {
        response.status(404).json({ error: "Report not found." });
        return;
      }

      await deleteStoredImage(report.image).catch((imageError) => {
        console.error("[DELETE /api/reports/:id] Image cleanup failed:", imageError);
      });

      response.json({ message: "Report deleted.", id: report.id });
    } catch (error) {
      next(error);
    }
  },
);

app.use((_request, response) => {
  response.status(404).json({ error: "Route not found." });
});

app.use((error, _request, response, _next) => {
  console.error("CivicGuard request error:", error);

  if (error instanceof multer.MulterError) {
    const status = error.code === "LIMIT_FILE_SIZE" ? 413 : 400;
    response.status(status).json({ error: error.message });
    return;
  }

  if (error instanceof SyntaxError && "body" in error) {
    response.status(400).json({ error: "Request body contains invalid JSON." });
    return;
  }

  if (error.message === "Uploaded file must be an image.") {
    response.status(400).json({ error: error.message });
    return;
  }

  const isMissingApiKey =
    typeof error.message === "string" &&
    error.message.includes("GEMINI_API_KEY is not configured");
  const status = isMissingApiKey ? 503 : 500;
  const message =
    process.env.NODE_ENV === "production"
      ? "An unexpected server error occurred."
      : error.message || "An unexpected server error occurred.";

  response.status(status).json({ error: message });
});

const port = Number.parseInt(process.env.PORT ?? "5000", 10);
if (!Number.isInteger(port) || port < 1 || port > 65535) {
  throw new Error("PORT must be an integer between 1 and 65535.");
}

async function startServer() {
  try {
    await getReports();
    await getJwtSecret();
    await ensureImageStorageReady();
    app.listen(port, () => {
      console.log(`CivicGuard API listening on port ${port}`);
    });
  } catch (error) {
    console.error("Failed to load persisted CivicGuard reports:", error);
    process.exitCode = 1;
  }
}

startServer();

export default app;

import { useEffect, useMemo, useState } from "react";

const API_URL = "http://localhost:5000/api/reports";
const REFRESH_INTERVAL_MS = 5000;

const urgencyStyles = {
  low: "border-mint/25 bg-mint/10 text-mint",
  medium: "border-yellow-400/25 bg-yellow-400/10 text-yellow-300",
  high: "border-amber-400/25 bg-amber-400/10 text-amber-300",
  critical: "border-alert/30 bg-alert/10 text-alert",
};

const categoryStyles = {
  pothole: "text-alert",
  streetlight: "text-cyan",
  accessibility: "text-mint",
  garbage: "text-yellow-300",
};

const categories = ["All", "Pothole", "Streetlight", "Accessibility", "Garbage"];

function getSeverity(value) {
  if (typeof value === "string") {
    const normalized = value.trim().toLowerCase();
    const severityByLabel = {
      low: 1,
      minor: 1,
      medium: 3,
      moderate: 3,
      high: 4,
      severe: 4,
      critical: 5,
    };

    if (normalized in severityByLabel) return severityByLabel[normalized];
  }

  const score = Number(value);
  return Number.isFinite(score) && score >= 1 && score <= 5
    ? Math.round(score)
    : null;
}

function getUrgency(value, severity) {
  const normalized = typeof value === "string" ? value.trim().toLowerCase() : "";
  if (["low", "medium", "high", "critical"].includes(normalized)) {
    return normalized;
  }

  if (severity === null) return "medium";
  if (severity >= 5) return "critical";
  if (severity >= 4) return "high";
  if (severity >= 3) return "medium";
  return "low";
}

function getReportDetails(report) {
  const analysis =
    report.analysis && typeof report.analysis === "object" ? report.analysis : {};
  const category = String(report.category ?? analysis.category ?? "Uncategorized");
  const description = String(
    report.description ?? analysis.summary ?? analysis.description ?? "No description provided.",
  );
  const severity = getSeverity(
    analysis.severityScore ??
      analysis.severity_score ??
      analysis.severity ??
      report.severityScore ??
      report.severity,
  );
  const urgency = getUrgency(
    analysis.urgencyLevel ?? analysis.urgency ?? report.urgencyLevel ?? report.urgency,
    severity,
  );
  const timestamp = report.timestamp ?? report.createdAt ?? report.created_at;
  const date = timestamp ? new Date(timestamp) : null;

  return {
    id: report.id,
    title: String(
      report.title ?? analysis.title ?? analysis.issueTitle ?? `${category} report`,
    ),
    category,
    district: String(report.district ?? "Unassigned"),
    description,
    severity,
    urgency,
    status: typeof report.status === "string" ? report.status : "Pending",
      tags: Array.isArray(analysis.tags) ? analysis.tags.filter((tag) => typeof tag === "string") : [],
      hasImage: Boolean(report.image),
      imageUrl: typeof report.image?.url === "string" ? report.image.url : null,
    timestamp:
      date && !Number.isNaN(date.getTime())
        ? new Intl.DateTimeFormat(undefined, {
            dateStyle: "medium",
            timeStyle: "short",
          }).format(date)
        : "Time unavailable",
  };
}

function SeverityIndicator({ score }) {
  const activeColor = score >= 5 ? "bg-alert" : score >= 3 ? "bg-cyan" : "bg-mint";

  return (
    <div aria-label={score ? `Severity ${score} out of 5` : "Severity not rated"} role="img">
      <div aria-hidden="true" className="mt-2 grid h-1.5 grid-cols-5 gap-1">
        {[1, 2, 3, 4, 5].map((level) => (
          <span
            className={`rounded-full ${
              score !== null && level <= score ? `${activeColor} shadow-[0_0_7px_currentColor]` : "bg-white/10"
            }`}
            key={level}
          />
        ))}
      </div>
      <p className="mt-1.5 font-mono text-[10px] text-muted">
        {score === null ? "Not rated" : `${score} / 5`}
      </p>
    </div>
  );
}

