              <span>District:</span>
              <select
                className="max-w-40 cursor-pointer bg-transparent font-mono text-[10px] font-semibold text-mint outline-none"
                onChange={(event) => setDistrictFilter(event.target.value)}
                value={districtFilter}
              >
                {districts.map((district) => (
